CREATE OR REPLACE FUNCTION "public"."abandon_program_enrollment"("p_enrollment_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id UUID := auth.uid();
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  UPDATE program_enrollments SET
    status = 'abandoned',
    abandoned_at = NOW(),
    updated_at = NOW()
  WHERE id = p_enrollment_id
    AND user_id = v_user_id
    AND status IN ('active', 'paused');

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Enrollment not found, not owned by user, or already completed/abandoned';
  END IF;
END;
$$;


ALTER FUNCTION "public"."abandon_program_enrollment"("p_enrollment_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."abandon_sessions_on_partnership_end"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    IF NEW.status = 'ended' AND OLD.status IN ('pending', 'active') THEN
        UPDATE couples_exercise_sessions
        SET 
            status = 'abandoned',
            updated_at = now()
        WHERE 
            partner_link_id = NEW.id
            AND status IN ('pending', 'in_progress', 'paused');
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."abandon_sessions_on_partnership_end"() OWNER TO "postgres";

