CREATE TABLE IF NOT EXISTS "public"."buddy_relationships" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "inviter_id" "uuid" NOT NULL,
    "invitee_id" "uuid",
    "invite_code" "text" NOT NULL,
    "invite_method" "text",
    "invitee_contact" "text",
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "invited_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "accepted_at" timestamp with time zone,
    "buddy_circle_id" "uuid",
    "inviter_reward_claimed" boolean DEFAULT false NOT NULL,
    "invitee_reward_claimed" boolean DEFAULT false NOT NULL,
    "expires_at" timestamp with time zone DEFAULT ("now"() + '30 days'::interval) NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "buddy_relationships_invite_method_check" CHECK (("invite_method" = ANY (ARRAY['sms'::"text", 'email'::"text", 'link'::"text"]))),
    CONSTRAINT "buddy_relationships_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'accepted'::"text", 'declined'::"text", 'expired'::"text"])))
);


ALTER TABLE "public"."buddy_relationships" OWNER TO "postgres";


COMMENT ON TABLE "public"."buddy_relationships" IS 'Tracks wellness buddy pairs from onboarding invites';



CREATE OR REPLACE FUNCTION "public"."accept_buddy_invite"("p_invite_code" "text", "p_user_id" "uuid") RETURNS "public"."buddy_relationships"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_relationship buddy_relationships;
  v_circle_id UUID;
  v_inviter_name TEXT;
  v_xp_reward INT := 100;
BEGIN
  -- Find and validate invite
  SELECT * INTO v_relationship
  FROM buddy_relationships
  WHERE invite_code = UPPER(p_invite_code)
    AND status = 'pending'
    AND expires_at > NOW()
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Invalid or expired invite code';
  END IF;

  -- Prevent self-buddy
  IF v_relationship.inviter_id = p_user_id THEN
    RAISE EXCEPTION 'Cannot accept your own invite';
  END IF;

  -- Get inviter name for circle
  SELECT display_name INTO v_inviter_name
  FROM profiles
  WHERE id = v_relationship.inviter_id;

  -- Create buddy circle (2-person private circle)
  INSERT INTO circles (name, description, owner_id, max_members, invite_code)
  VALUES (
    'Buddies',
    'Your wellness buddy circle',
    v_relationship.inviter_id,
    2,
    'BUDDY-' || UPPER(SUBSTRING(MD5(v_relationship.id::TEXT) FROM 1 FOR 6))
  )
  RETURNING id INTO v_circle_id;

  -- Add both users as circle members
  INSERT INTO circle_members (circle_id, user_id, role, joined_at)
  VALUES
    (v_circle_id, v_relationship.inviter_id, 'owner', NOW()),
    (v_circle_id, p_user_id, 'member', NOW());

  -- Update buddy relationship
  UPDATE buddy_relationships SET
    invitee_id = p_user_id,
    status = 'accepted',
    accepted_at = NOW(),
    buddy_circle_id = v_circle_id
  WHERE id = v_relationship.id
  RETURNING * INTO v_relationship;

  -- Update invitee profile: link referral and give fresh start bonus
  UPDATE profiles SET
    referred_by = v_relationship.inviter_id,
    current_streak_days = 2  -- Fresh start bonus: Day 2 streak
  WHERE id = p_user_id;

  -- Update inviter profile: increment referral count and add XP
  UPDATE profiles SET
    total_referrals = total_referrals + 1,
    xp_total = COALESCE(xp_total, 0) + v_xp_reward
  WHERE id = v_relationship.inviter_id;

  -- Award "Good Friend" badge to inviter if first referral
  INSERT INTO user_badges (user_id, badge_id)
  SELECT v_relationship.inviter_id, b.id
  FROM badges b
  WHERE b.code = 'good_friend'
  ON CONFLICT (user_id, badge_id) DO NOTHING;

  RETURN v_relationship;
END;
$$;


ALTER FUNCTION "public"."accept_buddy_invite"("p_invite_code" "text", "p_user_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."accept_buddy_invite"("p_invite_code" "text", "p_user_id" "uuid") IS 'Handles accepting a buddy invite: creates circle, links profiles, awards bonuses';



CREATE OR REPLACE FUNCTION "public"."accept_mentorship"("p_mentorship_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_user_id UUID := auth.uid();
BEGIN
    IF v_user_id IS NULL THEN
        RAISE EXCEPTION 'Not authenticated';
    END IF;

    UPDATE mentorships
    SET
        status = 'active',
        started_at = NOW(),
        next_checkin_due = NOW() + INTERVAL '7 days',
        updated_at = NOW()
    WHERE id = p_mentorship_id
    AND mentor_id = v_user_id
    AND status = 'pending';

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Mentorship not found or not authorized';
    END IF;

    RETURN TRUE;
END;
$$;


ALTER FUNCTION "public"."accept_mentorship"("p_mentorship_id" "uuid") OWNER TO "postgres";


