CREATE OR REPLACE FUNCTION "public"."add_family_member"("p_family_id" "uuid", "p_user_id" "uuid", "p_role" "text" DEFAULT 'child'::"text", "p_nickname" "text" DEFAULT NULL::"text", "p_birth_date" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_family_record RECORD;
  v_existing_member RECORD;
  v_member_record RECORD;
  v_error_code TEXT;
BEGIN
  -- Step 0: CRITICAL SECURITY CHECK - Users can only add themselves to families
  -- Prevents IDOR privilege escalation where user A adds user B without consent
  IF p_user_id != auth.uid() THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Unauthorized: can only add yourself to a family',
      'code', 'UNAUTHORIZED'
    );
  END IF;

  -- Step 1: Lock family_groups row for atomic check-and-insert
  -- FOR UPDATE prevents concurrent modifications to this family
  SELECT id, max_members
  INTO v_family_record
  FROM family_groups
  WHERE id = p_family_id
  FOR UPDATE;

  -- Step 2: Family not found
  IF v_family_record IS NULL THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Family not found',
      'code', 'FAMILY_NOT_FOUND'
    );
  END IF;

  -- Step 3: Check if user is already a member (prevent duplicates)
  SELECT id INTO v_existing_member
  FROM family_members
  WHERE family_id = p_family_id
    AND user_id = p_user_id
    AND status = 'active'
  LIMIT 1;

  IF v_existing_member IS NOT NULL THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'User is already a member of this family',
      'code', 'ALREADY_MEMBER'
    );
  END IF;

  -- Step 4: Check member limit (atomic check within same transaction)
  -- Count active members and verify against max_members
  -- Using COUNT(*) LIMIT 1 pattern prevents unnecessary full table scan
  IF (
    SELECT COUNT(*)
    FROM family_members
    WHERE family_id = p_family_id
      AND status = 'active'
  ) >= COALESCE(v_family_record.max_members, 6) THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Family has reached maximum members',
      'code', 'MEMBER_LIMIT_EXCEEDED'
    );
  END IF;

  -- Step 5: Insert new family member (atomic - within same transaction with lock held)
  INSERT INTO family_members (
    family_id,
    user_id,
    role,
    nickname,
    birth_date,
    status,
    joined_at,
    created_at,
    updated_at
  )
  VALUES (
    p_family_id,
    p_user_id,
    p_role,
    p_nickname,
    CASE WHEN p_birth_date IS NOT NULL AND p_birth_date != '' THEN p_birth_date::DATE ELSE NULL END,
    'active',
    NOW(),
    NOW(),
    NOW()
  )
  RETURNING * INTO v_member_record;

  -- Step 6: Return success with member details
  RETURN jsonb_build_object(
    'success', true,
    'member_id', v_member_record.id,
    'user_id', v_member_record.user_id,
    'family_id', v_member_record.family_id,
    'role', v_member_record.role,
    'joined_at', v_member_record.joined_at
  );

EXCEPTION WHEN OTHERS THEN
  -- Log unexpected errors and return generic failure
  RETURN jsonb_build_object(
    'success', false,
    'error', 'Failed to add family member',
    'code', 'RPC_ERROR'
  );
END;
$$;


ALTER FUNCTION "public"."add_family_member"("p_family_id" "uuid", "p_user_id" "uuid", "p_role" "text", "p_nickname" "text", "p_birth_date" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."add_family_member"("p_family_id" "uuid", "p_user_id" "uuid", "p_role" "text", "p_nickname" "text", "p_birth_date" "text") IS 'Atomically add user to family with IDOR prevention (users can only add themselves)';



CREATE OR REPLACE FUNCTION "public"."aggregate_daily_signals"("p_user_id" "uuid", "p_date" "date" DEFAULT CURRENT_DATE) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_signal_id UUID;
    v_mood_stats RECORD;
    v_engagement_stats RECORD;
    v_social_stats RECORD;
    v_biometric_id UUID;
    v_streak INTEGER;
    v_streak_broken BOOLEAN;
BEGIN
    -- Calculate mood statistics for the day
    SELECT
        AVG(mood_score)::DECIMAL(3,1) as avg_mood,
        MIN(mood_score) as min_mood,
        MAX(mood_score) as max_mood,
        VARIANCE(mood_score)::DECIMAL(4,2) as variance,
        COUNT(*) as count
    INTO v_mood_stats
    FROM moods
    WHERE user_id = p_user_id
    AND DATE(created_at) = p_date;

    -- Calculate engagement statistics
    SELECT
        COALESCE(COUNT(*) FILTER (WHERE completed_at IS NOT NULL), 0) as quests_completed,
        COALESCE((SELECT COUNT(*) FROM exercise_sessions es WHERE es.user_id = p_user_id AND DATE(es.created_at) = p_date), 0) as exercises_completed,
        COALESCE((SELECT COUNT(*) FROM messages m WHERE m.user_id = p_user_id AND DATE(m.created_at) = p_date AND m.role = 'user'), 0) as chat_messages
    INTO v_engagement_stats
    FROM quests
    WHERE user_id = p_user_id
    AND DATE(created_at) = p_date;

    -- Calculate social statistics
    SELECT
        COALESCE(COUNT(*), 0) as posts,
        COALESCE((SELECT COUNT(*) FROM circle_reactions cr
                  JOIN circle_posts cp ON cr.post_id = cp.id
                  WHERE cp.user_id = p_user_id AND DATE(cr.created_at) = p_date), 0) as reactions_received
    INTO v_social_stats
    FROM circle_posts
    WHERE user_id = p_user_id
    AND DATE(created_at) = p_date;

    -- Get biometric summary ID if exists
    SELECT id INTO v_biometric_id
    FROM biometric_daily_summaries
    WHERE user_id = p_user_id AND date = p_date;

    -- Get current streak
    SELECT current_streak INTO v_streak
    FROM profiles
    WHERE id = p_user_id;

    -- Check if streak was broken today (simplified check)
    v_streak_broken := (v_streak = 0 AND EXISTS (
        SELECT 1 FROM profiles WHERE id = p_user_id AND updated_at::DATE = p_date
    ));

    -- Upsert daily signals
    INSERT INTO daily_signals (
        user_id,
        signal_date,
        biometric_summary_id,
        mood_average,
        mood_min,
        mood_max,
        mood_variance,
        mood_entry_count,
        quests_completed,
        exercises_completed,
        chat_messages_sent,
        circle_posts,
        circle_reactions_received,
        current_streak,
        streak_broken_today,
        -- Compute composite scores
        engagement_score,
        social_score
    ) VALUES (
        p_user_id,
        p_date,
        v_biometric_id,
        v_mood_stats.avg_mood,
        v_mood_stats.min_mood,
        v_mood_stats.max_mood,
        v_mood_stats.variance,
        COALESCE(v_mood_stats.count, 0),
        v_engagement_stats.quests_completed,
        v_engagement_stats.exercises_completed,
        v_engagement_stats.chat_messages,
        v_social_stats.posts,
        v_social_stats.reactions_received,
        COALESCE(v_streak, 0),
        v_streak_broken,
        -- Engagement score: 0-100 based on activity
        LEAST(100, (
            v_engagement_stats.quests_completed * 20 +
            v_engagement_stats.exercises_completed * 15 +
            v_engagement_stats.chat_messages * 5
        )),
        -- Social score: 0-100 based on circle activity
        LEAST(100, (
            v_social_stats.posts * 25 +
            v_social_stats.reactions_received * 10
        ))
    )
    ON CONFLICT (user_id, signal_date) DO UPDATE SET
        biometric_summary_id = EXCLUDED.biometric_summary_id,
        mood_average = EXCLUDED.mood_average,
        mood_min = EXCLUDED.mood_min,
        mood_max = EXCLUDED.mood_max,
        mood_variance = EXCLUDED.mood_variance,
        mood_entry_count = EXCLUDED.mood_entry_count,
        quests_completed = EXCLUDED.quests_completed,
        exercises_completed = EXCLUDED.exercises_completed,
        chat_messages_sent = EXCLUDED.chat_messages_sent,
        circle_posts = EXCLUDED.circle_posts,
        circle_reactions_received = EXCLUDED.circle_reactions_received,
        current_streak = EXCLUDED.current_streak,
        streak_broken_today = EXCLUDED.streak_broken_today,
        engagement_score = EXCLUDED.engagement_score,
        social_score = EXCLUDED.social_score,
        updated_at = NOW()
    RETURNING id INTO v_signal_id;

    RETURN v_signal_id;
END;
$$;


ALTER FUNCTION "public"."aggregate_daily_signals"("p_user_id" "uuid", "p_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_to_become_listener"("p_display_name" "text" DEFAULT NULL::"text", "p_bio" "text" DEFAULT NULL::"text", "p_specializations" "text"[] DEFAULT ARRAY[]::"text"[], "p_languages" "text"[] DEFAULT ARRAY['en'::"text"]) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_user_id UUID := auth.uid();
    v_listener_id UUID;
    v_days_on_platform INTEGER;
    v_exercises_completed INTEGER;
BEGIN
    IF v_user_id IS NULL THEN
        RAISE EXCEPTION 'Not authenticated';
    END IF;

    -- Check eligibility: 30+ days on platform
    SELECT EXTRACT(EPOCH FROM (NOW() - created_at)) / 86400
    INTO v_days_on_platform
    FROM profiles
    WHERE id = v_user_id;

    IF v_days_on_platform < 30 THEN
        RAISE EXCEPTION 'Must have 30+ days on platform to apply';
    END IF;

    -- Check eligibility: 10+ exercises completed
    SELECT COUNT(*)
    INTO v_exercises_completed
    FROM exercise_sessions
    WHERE user_id = v_user_id AND completed_at IS NOT NULL;

    IF v_exercises_completed < 10 THEN
        RAISE EXCEPTION 'Must complete 10+ exercises to apply';
    END IF;

    -- Check if already a listener
    SELECT id INTO v_listener_id
    FROM listeners
    WHERE user_id = v_user_id;

    IF v_listener_id IS NOT NULL THEN
        RAISE EXCEPTION 'Already applied or registered as listener';
    END IF;

    -- Create listener application
    INSERT INTO listeners (
        user_id,
        status,
        display_name,
        bio,
        specializations,
        languages
    )
    VALUES (
        v_user_id,
        'applicant',
        COALESCE(p_display_name, (SELECT display_name FROM profiles WHERE id = v_user_id)),
        p_bio,
        p_specializations,
        p_languages
    )
    RETURNING id INTO v_listener_id;

    RETURN v_listener_id;
END;
$$;


ALTER FUNCTION "public"."apply_to_become_listener"("p_display_name" "text", "p_bio" "text", "p_specializations" "text"[], "p_languages" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."assign_daily_quest"("p_local_date" "text") RETURNS TABLE("id" "uuid", "user_id" "uuid", "template_id" "uuid", "local_date" "text", "status" "text", "assigned_at" timestamp with time zone, "completed_at" timestamp with time zone, "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id UUID;
  v_existing_quest RECORD;
  v_template_id UUID;
BEGIN
  -- Get the authenticated user
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  -- Check if quest already exists for this date (idempotent)
  SELECT q.* INTO v_existing_quest
  FROM quests q
  WHERE q.user_id = v_user_id AND q.local_date = p_local_date;

  IF FOUND THEN
    -- Return existing quest
    RETURN QUERY
    SELECT q.id, q.user_id, q.template_id, q.local_date, q.status,
           q.assigned_at, q.completed_at, q.created_at
    FROM quests q
    WHERE q.id = v_existing_quest.id;
    RETURN;
  END IF;

  -- Select a random quest template (prefer ones not recently assigned)
  SELECT qt.id INTO v_template_id
  FROM quest_templates qt
  WHERE qt.is_active = true
    AND qt.id NOT IN (
      SELECT q.template_id
      FROM quests q
      WHERE q.user_id = v_user_id
        AND q.local_date >= (p_local_date::DATE - INTERVAL '7 days')::TEXT
    )
  ORDER BY RANDOM()
  LIMIT 1;

  -- If all templates used recently, pick any active one
  IF v_template_id IS NULL THEN
    SELECT qt.id INTO v_template_id
    FROM quest_templates qt
    WHERE qt.is_active = true
    ORDER BY RANDOM()
    LIMIT 1;
  END IF;

  -- If still no template, raise error
  IF v_template_id IS NULL THEN
    RAISE EXCEPTION 'No active quest templates available';
  END IF;

  -- Insert new quest and return it
  RETURN QUERY
  INSERT INTO quests (user_id, template_id, local_date, status, assigned_at, created_at)
  VALUES (v_user_id, v_template_id, p_local_date, 'assigned', NOW(), NOW())
  RETURNING quests.id, quests.user_id, quests.template_id, quests.local_date,
            quests.status, quests.assigned_at, quests.completed_at, quests.created_at;
END;
$$;


ALTER FUNCTION "public"."assign_daily_quest"("p_local_date" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."assign_daily_quest"("p_user_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER COST 500
    SET "search_path" TO 'public'
    AS $$
declare
    v_quest_id uuid;
    v_user_quest_id uuid;
    v_is_premium boolean;
begin
    -- Check if user already has quest for today
    select id into v_user_quest_id
    from public.user_quests
    where user_id = p_user_id and assigned_date = current_date;

    if v_user_quest_id is not null then
        return v_user_quest_id;
    end if;

    -- Get user's subscription tier
    select subscription_tier = 'premium' into v_is_premium
    from public.profiles where id = p_user_id;

    -- Pick a random quest template
    select id into v_quest_id
    from public.quest_templates
    where (not is_premium or v_is_premium)
    order by random()
    limit 1;

    -- Create user quest
    insert into public.user_quests (user_id, quest_template_id, assigned_date)
    values (p_user_id, v_quest_id, current_date)
    returning id into v_user_quest_id;

    return v_user_quest_id;
end;
$$;


