CREATE OR REPLACE FUNCTION "public"."calculate_assessment_severity"("p_assessment_type" "text", "p_total_score" integer) RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
BEGIN
    IF p_assessment_type = 'phq9' THEN
        -- PHQ-9 severity levels (max score 27)
        IF p_total_score >= 20 THEN RETURN 'severe';
        ELSIF p_total_score >= 15 THEN RETURN 'moderately_severe';
        ELSIF p_total_score >= 10 THEN RETURN 'moderate';
        ELSIF p_total_score >= 5 THEN RETURN 'mild';
        ELSE RETURN 'minimal';
        END IF;
    ELSIF p_assessment_type = 'gad7' THEN
        -- GAD-7 severity levels (max score 21)
        IF p_total_score >= 15 THEN RETURN 'severe';
        ELSIF p_total_score >= 10 THEN RETURN 'moderate';
        ELSIF p_total_score >= 5 THEN RETURN 'mild';
        ELSE RETURN 'minimal';
        END IF;
    ELSE
        RETURN 'minimal';
    END IF;
END;
$$;


ALTER FUNCTION "public"."calculate_assessment_severity"("p_assessment_type" "text", "p_total_score" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calculate_level"("total_xp" integer) RETURNS integer
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
BEGIN
    -- Level formula: level = floor(sqrt(total_xp / 50)) + 1
    -- Requires progressively more XP per level
    RETURN GREATEST(1, FLOOR(SQRT(total_xp::NUMERIC / 50)) + 1);
END;
$$;


ALTER FUNCTION "public"."calculate_level"("total_xp" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calculate_mood_trend"("p_days" integer DEFAULT 7) RETURNS TABLE("trend" "text", "consecutive_low" integer, "avg_recent" double precision, "avg_previous" double precision, "today_mood" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_user_id UUID;
    v_recent FLOAT;
    v_previous FLOAT;
    v_consecutive INT := 0;
    v_today_mood INT;
    v_trend TEXT;
BEGIN
    -- SECURITY: Get authenticated user ID (no user-controlled parameter)
    v_user_id := auth.uid();
    IF v_user_id IS NULL THEN
        RAISE EXCEPTION 'Not authenticated';
    END IF;

    -- Get today's mood (FIXED: use DATE = DATE comparison)
    SELECT mood_score INTO v_today_mood
    FROM moods
    WHERE user_id = v_user_id
        AND local_date = CURRENT_DATE
    LIMIT 1;

    -- Recent average (last N/2 days)
    SELECT AVG(mood_score)::FLOAT INTO v_recent
    FROM moods
    WHERE user_id = v_user_id
        AND created_at > NOW() - ((p_days / 2) || ' days')::INTERVAL;

    -- Previous average (N/2 to N days ago)
    SELECT AVG(mood_score)::FLOAT INTO v_previous
    FROM moods
    WHERE user_id = v_user_id
        AND created_at > NOW() - (p_days || ' days')::INTERVAL
        AND created_at <= NOW() - ((p_days / 2) || ' days')::INTERVAL;

    -- Count consecutive low mood days (mood <= 2)
    -- Start from most recent and count backwards
    WITH recent_moods AS (
        SELECT m.local_date, m.mood_score,
               ROW_NUMBER() OVER (ORDER BY m.local_date DESC) as rn
        FROM moods m
        WHERE m.user_id = v_user_id
        ORDER BY m.local_date DESC
        LIMIT p_days
    )
    SELECT COUNT(*) INTO v_consecutive
    FROM (
        SELECT local_date, mood_score, rn,
               SUM(CASE WHEN mood_score > 2 THEN 1 ELSE 0 END) OVER (ORDER BY rn) as break_count
        FROM recent_moods
    ) sub
    WHERE break_count = 0 AND mood_score <= 2;

    -- Determine trend
    IF v_recent IS NULL OR v_previous IS NULL THEN
        v_trend := 'stable';
    ELSIF v_recent > v_previous + 0.5 THEN
        v_trend := 'improving';
    ELSIF v_recent < v_previous - 0.5 THEN
        v_trend := 'declining';
    ELSE
        v_trend := 'stable';
    END IF;

    RETURN QUERY SELECT v_trend, v_consecutive, v_recent, v_previous, v_today_mood;
END;
$$;


ALTER FUNCTION "public"."calculate_mood_trend"("p_days" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."calculate_mood_trend"("p_days" integer) IS 'Calculate mood trend - fixed DATE comparison (moods.local_date is DATE type)';



