CREATE OR REPLACE FUNCTION "public"."calculate_reply_depth"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF NEW.parent_reply_id IS NULL THEN
    NEW.depth := 0;
  ELSE
    SELECT depth + 1 INTO NEW.depth
    FROM forum_replies
    WHERE id = NEW.parent_reply_id;

    IF NEW.depth > 5 THEN
      RAISE EXCEPTION 'Maximum reply depth (5 levels) exceeded';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


