CREATE OR REPLACE FUNCTION "public"."calculate_user_absence"("p_user_id" "uuid") RETURNS TABLE("absence_days" integer, "lapse_tier" "text", "hugs_received" integer, "circle_posts" integer, "friend_milestones" "jsonb")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_last_session TIMESTAMPTZ;
  v_days INT;
  v_tier TEXT;
  v_hugs INT;
  v_posts INT;
  v_milestones JSONB;
BEGIN
  -- Get last session
  SELECT last_session_at INTO v_last_session FROM profiles WHERE id = p_user_id;

  -- Calculate days absent
  v_days := COALESCE(EXTRACT(DAY FROM NOW() - v_last_session)::INT, 0);

  -- Determine tier per spec
  v_tier := CASE
    WHEN v_days < 3 THEN 'active'
    WHEN v_days < 7 THEN 'brief_break'
    WHEN v_days < 14 THEN 'extended_break'
    WHEN v_days < 30 THEN 'long_absence'
    ELSE 'hiatus'
  END;

  -- Count hugs received since last session
  SELECT COUNT(*)::INT INTO v_hugs
  FROM circle_hugs
  WHERE recipient_id = p_user_id
    AND created_at > COALESCE(v_last_session, NOW() - INTERVAL '30 days');

  -- Count circle posts from others in user's circles
  SELECT COUNT(*)::INT INTO v_posts
  FROM circle_posts cp
  JOIN circle_members cm ON cm.circle_id = cp.circle_id
  WHERE cm.user_id = p_user_id
    AND cp.user_id != p_user_id
    AND cp.created_at > COALESCE(v_last_session, NOW() - INTERVAL '30 days');

  -- Get friend milestones (streak achievements, badges, etc.)
  SELECT COALESCE(json_agg(json_build_object(
    'name', p.display_name,
    'milestone', cp.body_text,
    'isStreak', CASE WHEN cp.body_text ILIKE '%streak%' THEN TRUE ELSE FALSE END
  )), '[]'::json)::jsonb INTO v_milestones
  FROM circle_posts cp
  JOIN profiles p ON p.id = cp.user_id
  JOIN circle_members cm ON cm.circle_id = cp.circle_id
  WHERE cm.user_id = p_user_id
    AND cp.kind = 'milestone'
    AND cp.user_id != p_user_id
    AND cp.created_at > COALESCE(v_last_session, NOW() - INTERVAL '30 days')
  LIMIT 5;

  -- Return the results
  RETURN QUERY SELECT v_days, v_tier, COALESCE(v_hugs, 0), COALESCE(v_posts, 0), COALESCE(v_milestones, '[]'::jsonb);
END;
$$;


ALTER FUNCTION "public"."calculate_user_absence"("p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calculate_user_absence_batch"("p_user_ids" "uuid"[]) RETURNS TABLE("user_id" "uuid", "absence_days" integer, "lapse_tier" "text", "hugs_received" integer, "circle_posts" integer, "friend_milestones" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH user_last_activity AS (
    SELECT
      p.id AS user_id,
      EXTRACT(DAY FROM (NOW() - COALESCE(p.updated_at, p.created_at)))::INT AS days_absent
    FROM profiles p
    WHERE p.id = ANY(p_user_ids)
  ),
  lapse_tiers AS (
    SELECT
      user_id,
      CASE
        WHEN days_absent >= 30 THEN 'hibernating'
        WHEN days_absent >= 14 THEN 'lapsed'
        WHEN days_absent >= 7 THEN 'drifting'
        WHEN days_absent >= 3 THEN 'at_risk'
        ELSE 'active'
      END AS lapse_tier
    FROM user_last_activity
  )
  SELECT
    ula.user_id,
    ula.days_absent,
    lt.lapse_tier,
    0::INT AS hugs_received,  -- TODO: implement
    0::INT AS circle_posts,  -- TODO: implement
    0::INT AS friend_milestones  -- TODO: implement
  FROM user_last_activity ula
  JOIN lapse_tiers lt ON lt.user_id = ula.user_id;
$$;


ALTER FUNCTION "public"."calculate_user_absence_batch"("p_user_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calculate_user_send_time"("p_user_id" "uuid", "p_target_hour" integer, "p_target_day_of_week" integer DEFAULT NULL::integer, "p_target_day_of_month" integer DEFAULT NULL::integer) RETURNS timestamp with time zone
    LANGUAGE "plpgsql" STABLE
    AS $$
DECLARE
    v_timezone TEXT;
    v_user_tz TIMESTAMPTZ;
    v_utc_time TIMESTAMPTZ;
BEGIN
    -- Get user's timezone from preferences
    SELECT timezone INTO v_timezone FROM email_preferences WHERE user_id = p_user_id;
    IF v_timezone IS NULL THEN
        v_timezone := 'America/New_York';
    END IF;

    -- Start with current time in user's timezone
    v_user_tz := NOW() AT TIME ZONE v_timezone;

    -- Adjust for weekly scheduling (day of week)
    IF p_target_day_of_week IS NOT NULL THEN
        -- 0 = Sunday, 1 = Monday, ..., 6 = Saturday
        WHILE EXTRACT(DOW FROM v_user_tz) != p_target_day_of_week LOOP
            v_user_tz := v_user_tz + INTERVAL '1 day';
        END LOOP;
    END IF;

    -- Adjust for monthly scheduling (day of month)
    IF p_target_day_of_month IS NOT NULL THEN
        v_user_tz := DATE_TRUNC('month', v_user_tz) + ((p_target_day_of_month - 1) || ' day')::INTERVAL;
    END IF;

    -- Set to target hour (truncate to start of day, then add hours)
    v_user_tz := DATE_TRUNC('day', v_user_tz) + (p_target_hour || ' hour')::INTERVAL;

    -- If time is in the past, advance to next occurrence
    IF v_user_tz < NOW() AT TIME ZONE v_timezone THEN
        IF p_target_day_of_week IS NOT NULL THEN
            v_user_tz := v_user_tz + INTERVAL '7 days';
        ELSIF p_target_day_of_month IS NOT NULL THEN
            v_user_tz := v_user_tz + INTERVAL '1 month';
        ELSE
            v_user_tz := v_user_tz + INTERVAL '1 day';
        END IF;
    END IF;

    -- Convert back to UTC for storage
    v_utc_time := v_user_tz AT TIME ZONE v_timezone;

    RETURN v_utc_time;
END;
$$;


ALTER FUNCTION "public"."calculate_user_send_time"("p_user_id" "uuid", "p_target_hour" integer, "p_target_day_of_week" integer, "p_target_day_of_month" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calculate_weekly_stats"("p_user_id" "uuid") RETURNS TABLE("checkin_count" integer, "quest_count" integer, "exercise_count" integer, "avg_mood" double precision, "mood_trend" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_week_start TIMESTAMPTZ;
  v_prev_week_start TIMESTAMPTZ;
  v_this_week_avg FLOAT;
  v_prev_week_avg FLOAT;
  v_trend TEXT;
BEGIN
  -- Get start of current week (Monday)
  v_week_start := date_trunc('week', NOW());
  v_prev_week_start := v_week_start - INTERVAL '7 days';

  -- Calculate this week's average mood
  SELECT AVG(mood_score) INTO v_this_week_avg
  FROM moods
  WHERE user_id = p_user_id
    AND created_at >= v_week_start;

  -- Calculate previous week's average mood for trend
  SELECT AVG(mood_score) INTO v_prev_week_avg
  FROM moods
  WHERE user_id = p_user_id
    AND created_at >= v_prev_week_start
    AND created_at < v_week_start;

  -- Determine trend
  IF v_this_week_avg IS NULL OR v_prev_week_avg IS NULL THEN
    v_trend := 'stable';
  ELSIF v_this_week_avg > v_prev_week_avg + 0.5 THEN
    v_trend := 'improving';
  ELSIF v_this_week_avg < v_prev_week_avg - 0.5 THEN
    v_trend := 'declining';
  ELSE
    v_trend := 'stable';
  END IF;

  RETURN QUERY
  SELECT
    (SELECT COUNT(*)::int FROM moods WHERE user_id = p_user_id AND created_at >= v_week_start),
    (SELECT COUNT(*)::int FROM quests WHERE user_id = p_user_id AND status = 'completed' AND completed_at >= v_week_start),
    (SELECT COUNT(*)::int FROM exercise_sessions WHERE user_id = p_user_id AND created_at >= v_week_start),
    v_this_week_avg,
    v_trend;
END;
$$;


ALTER FUNCTION "public"."calculate_weekly_stats"("p_user_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."calculate_weekly_stats"("p_user_id" "uuid") IS 'Calculate weekly stats for a user (mood count, quests, exercises, mood trend)';



CREATE OR REPLACE FUNCTION "public"."calculate_weekly_stats_extended"("p_user_id" "uuid") RETURNS TABLE("checkin_count" integer, "quest_count" integer, "exercise_count" integer, "avg_mood" double precision, "avg_anxiety" double precision, "avg_energy" double precision, "mood_trend" "text", "anxiety_trend" "text", "energy_trend" "text", "mood_min" integer, "mood_max" integer, "mood_by_day" "jsonb", "circle_checkin_count" integer, "exercise_minutes" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_week_start TIMESTAMPTZ;
  v_prev_week_start TIMESTAMPTZ;
  -- This week's averages
  v_this_week_mood_avg FLOAT;
  v_this_week_anxiety_avg FLOAT;
  v_this_week_energy_avg FLOAT;
  -- Previous week's averages
  v_prev_week_mood_avg FLOAT;
  v_prev_week_anxiety_avg FLOAT;
  v_prev_week_energy_avg FLOAT;
  -- Trends
  v_mood_trend TEXT;
  v_anxiety_trend TEXT;
  v_energy_trend TEXT;
  -- Mood details
  v_mood_min INT;
  v_mood_max INT;
  v_mood_by_day JSONB;
  -- Counts
  v_checkin_count INT;
  v_quest_count INT;
  v_exercise_count INT;
  v_circle_count INT;
  v_exercise_mins INT;
BEGIN
  -- Get start of current week (Monday)
  v_week_start := date_trunc('week', NOW());
  v_prev_week_start := v_week_start - INTERVAL '7 days';

  -- Count mood checkins this week
  SELECT COUNT(*)::int INTO v_checkin_count
  FROM moods
  WHERE user_id = p_user_id
    AND created_at >= v_week_start;

  -- Calculate this week's mood, anxiety, and energy metrics
  SELECT
    AVG(mood_score),
    AVG(anxiety_score),
    AVG(energy_score),
    MIN(mood_score)::int,
    MAX(mood_score)::int
  INTO v_this_week_mood_avg, v_this_week_anxiety_avg, v_this_week_energy_avg, v_mood_min, v_mood_max
  FROM moods
  WHERE user_id = p_user_id
    AND created_at >= v_week_start;

  -- Calculate mood by day of week
  SELECT jsonb_object_agg(
    LOWER(day_name),
    ROUND(day_avg::numeric, 1)
  ) INTO v_mood_by_day
  FROM (
    SELECT
      TO_CHAR(created_at, 'Dy') as day_name,
      AVG(mood_score) as day_avg
    FROM moods
    WHERE user_id = p_user_id
      AND created_at >= v_week_start
    GROUP BY TO_CHAR(created_at, 'Dy'), EXTRACT(DOW FROM created_at)
    ORDER BY EXTRACT(DOW FROM created_at)
  ) daily_moods;

  -- Calculate previous week's averages for trends
  SELECT
    AVG(mood_score),
    AVG(anxiety_score),
    AVG(energy_score)
  INTO v_prev_week_mood_avg, v_prev_week_anxiety_avg, v_prev_week_energy_avg
  FROM moods
  WHERE user_id = p_user_id
    AND created_at >= v_prev_week_start
    AND created_at < v_week_start;

  -- Determine mood trend (require at least 3 moods for meaningful trend)
  IF v_checkin_count < 3 THEN
    v_mood_trend := 'insufficient_data';
  ELSIF v_this_week_mood_avg IS NULL OR v_prev_week_mood_avg IS NULL THEN
    v_mood_trend := 'stable';
  ELSIF v_this_week_mood_avg > v_prev_week_mood_avg + 0.5 THEN
    v_mood_trend := 'improving';
  ELSIF v_this_week_mood_avg < v_prev_week_mood_avg - 0.5 THEN
    v_mood_trend := 'declining';
  ELSE
    v_mood_trend := 'stable';
  END IF;

  -- Determine anxiety trend (lower anxiety is "improving")
  IF v_checkin_count < 3 THEN
    v_anxiety_trend := 'insufficient_data';
  ELSIF v_this_week_anxiety_avg IS NULL OR v_prev_week_anxiety_avg IS NULL THEN
    v_anxiety_trend := 'stable';
  ELSIF v_this_week_anxiety_avg < v_prev_week_anxiety_avg - 0.5 THEN
    v_anxiety_trend := 'improving';  -- Lower anxiety is better
  ELSIF v_this_week_anxiety_avg > v_prev_week_anxiety_avg + 0.5 THEN
    v_anxiety_trend := 'declining';  -- Higher anxiety is worse
  ELSE
    v_anxiety_trend := 'stable';
  END IF;

  -- Determine energy trend (higher energy is "improving")
  IF v_checkin_count < 3 THEN
    v_energy_trend := 'insufficient_data';
  ELSIF v_this_week_energy_avg IS NULL OR v_prev_week_energy_avg IS NULL THEN
    v_energy_trend := 'stable';
  ELSIF v_this_week_energy_avg > v_prev_week_energy_avg + 0.5 THEN
    v_energy_trend := 'improving';
  ELSIF v_this_week_energy_avg < v_prev_week_energy_avg - 0.5 THEN
    v_energy_trend := 'declining';
  ELSE
    v_energy_trend := 'stable';
  END IF;

  -- Count completed quests
  SELECT COUNT(*)::int INTO v_quest_count
  FROM quests
  WHERE user_id = p_user_id
    AND status = 'completed'
    AND completed_at >= v_week_start;

  -- Count exercises and total minutes
  SELECT
    COUNT(*)::int,
    COALESCE(SUM(EXTRACT(EPOCH FROM (ended_at - started_at)) / 60)::int, 0)
  INTO v_exercise_count, v_exercise_mins
  FROM exercise_sessions
  WHERE user_id = p_user_id
    AND created_at >= v_week_start
    AND completed = true;

  -- Count circle check-ins
  SELECT COUNT(*)::int INTO v_circle_count
  FROM circle_posts
  WHERE user_id = p_user_id
    AND kind = 'checkin'
    AND created_at >= v_week_start;

  RETURN QUERY SELECT
    v_checkin_count,
    v_quest_count,
    v_exercise_count,
    v_this_week_mood_avg,
    v_this_week_anxiety_avg,
    v_this_week_energy_avg,
    v_mood_trend,
    v_anxiety_trend,
    v_energy_trend,
    v_mood_min,
    v_mood_max,
    COALESCE(v_mood_by_day, '{}'::jsonb),
    v_circle_count,
    v_exercise_mins;
END;
$$;


