COMMENT ON FUNCTION "public"."calculate_weekly_stats_extended"("p_user_id" "uuid") IS 'Calculate extended weekly stats including mood, anxiety, energy averages and trends';



CREATE OR REPLACE FUNCTION "public"."check_and_increment_ai_quota"("p_user_id" "uuid", "p_is_premium" boolean DEFAULT false) RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_quota_used INT;
  v_quota_limit INT;
  v_quota_reset_at TIMESTAMPTZ;
  v_was_reset BOOLEAN := FALSE;
  v_profile_exists BOOLEAN;
  v_result JSON;
BEGIN
  -- Disable RLS
  SET LOCAL row_security = off;

  -- Check and create profile if needed
  SELECT COUNT(*) > 0 INTO v_profile_exists FROM profiles WHERE id = p_user_id;

  IF NOT v_profile_exists THEN
    INSERT INTO profiles (id, handle, display_name, email, daily_ai_used, daily_ai_quota, quota_reset_at)
    SELECT au.id, 'user_' || substr(md5(random()::text), 1, 8),
           COALESCE(au.raw_user_meta_data->>'full_name', 'MindFriend User'),
           au.email, 0, 10, NOW()
    FROM auth.users au WHERE au.id = p_user_id;

    INSERT INTO user_settings (user_id) VALUES (p_user_id) ON CONFLICT DO NOTHING;
    INSERT INTO user_stats (user_id) VALUES (p_user_id) ON CONFLICT DO NOTHING;
  END IF;

  -- Get quota info
  SELECT daily_ai_used, daily_ai_quota, quota_reset_at
  INTO v_quota_used, v_quota_limit, v_quota_reset_at
  FROM profiles WHERE id = p_user_id FOR UPDATE;

  -- Reset if new day
  IF DATE(v_quota_reset_at) < CURRENT_DATE THEN
    v_quota_used := 0;
    v_was_reset := TRUE;
    UPDATE profiles SET daily_ai_used = 0, quota_reset_at = NOW() WHERE id = p_user_id;
  END IF;

  -- Premium users
  IF p_is_premium THEN
    UPDATE profiles SET daily_ai_used = v_quota_used + 1 WHERE id = p_user_id;
    v_result := json_build_object('allowed', TRUE, 'quota_used', v_quota_used + 1, 'quota_limit', -1, 'was_reset', v_was_reset);
    RETURN v_result;
  END IF;

  -- Free users quota check
  IF v_quota_used >= v_quota_limit THEN
    v_result := json_build_object('allowed', FALSE, 'quota_used', v_quota_used, 'quota_limit', v_quota_limit, 'was_reset', v_was_reset);
    RETURN v_result;
  END IF;

  -- Increment
  UPDATE profiles SET daily_ai_used = v_quota_used + 1 WHERE id = p_user_id;
  v_result := json_build_object('allowed', TRUE, 'quota_used', v_quota_used + 1, 'quota_limit', v_quota_limit, 'was_reset', v_was_reset);
  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."check_and_increment_ai_quota"("p_user_id" "uuid", "p_is_premium" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_and_increment_content_quota"("p_user_id" "uuid", "p_is_premium" boolean DEFAULT false) RETURNS TABLE("allowed" boolean, "quota_used" integer, "quota_limit" integer, "was_reset" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_quota_used INT;
    v_quota_limit INT := 3;  -- Free tier: 3 generations per day
BEGIN
    -- Premium users: always allowed, no limit
    IF p_is_premium THEN
        -- Just count for analytics, no enforcement
        SELECT COUNT(*)::INT INTO v_quota_used
        FROM generated_content
        WHERE user_id = p_user_id
        AND DATE(created_at) = CURRENT_DATE
        AND status != 'failed';

        RETURN QUERY SELECT TRUE, v_quota_used, -1, FALSE;
        RETURN;
    END IF;

    -- Free users: count today's generations
    SELECT COUNT(*)::INT INTO v_quota_used
    FROM generated_content
    WHERE user_id = p_user_id
    AND DATE(created_at) = CURRENT_DATE
    AND status != 'failed';

    -- Check if user has already exceeded quota
    IF v_quota_used >= v_quota_limit THEN
        RETURN QUERY SELECT FALSE, v_quota_used, v_quota_limit, FALSE;
        RETURN;
    END IF;

    -- Quota not exceeded, allow generation
    RETURN QUERY SELECT TRUE, v_quota_used, v_quota_limit, FALSE;
END;
$$;


ALTER FUNCTION "public"."check_and_increment_content_quota"("p_user_id" "uuid", "p_is_premium" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."check_and_increment_content_quota"("p_user_id" "uuid", "p_is_premium" boolean) IS 'Checks content generation quota. Free: 3/day, Premium: unlimited.';



CREATE OR REPLACE FUNCTION "public"."check_and_increment_rehearsal_quota"("p_user_id" "uuid") RETURNS TABLE("can_create" boolean, "used" integer, "quota_limit" integer, "reset_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_used INTEGER;
    v_reset_at TIMESTAMPTZ;
    v_is_premium BOOLEAN;
    v_quota_limit INTEGER := 2; -- Free tier limit
    v_week_ago TIMESTAMPTZ := NOW() - INTERVAL '7 days';
BEGIN
    -- Check if user is premium
    SELECT subscription_tier = 'premium' INTO v_is_premium
    FROM profiles
    WHERE id = p_user_id;

    -- Premium users have unlimited quota
    IF v_is_premium THEN
        RETURN QUERY SELECT TRUE, 0, 999999, NOW();
        RETURN;
    END IF;

    -- Get or create user settings with row-level lock
    SELECT
        COALESCE(rehearsals_used_this_week, 0),
        COALESCE(rehearsals_quota_reset_at, NOW())
    INTO v_used, v_reset_at
    FROM user_settings
    WHERE user_id = p_user_id
    FOR UPDATE; -- Lock the row

    -- If no settings exist, create them
    IF NOT FOUND THEN
        INSERT INTO user_settings (user_id, rehearsals_used_this_week, rehearsals_quota_reset_at)
        VALUES (p_user_id, 0, NOW())
        RETURNING rehearsals_used_this_week, rehearsals_quota_reset_at
        INTO v_used, v_reset_at;
    END IF;

    -- Check if quota needs reset
    IF v_reset_at < v_week_ago THEN
        v_used := 0;
        v_reset_at := NOW();
    END IF;

    -- Check if user can create new session
    IF v_used < v_quota_limit THEN
        -- Increment quota usage atomically
        UPDATE user_settings
        SET
            rehearsals_used_this_week = v_used + 1,
            rehearsals_quota_reset_at = v_reset_at
        WHERE user_id = p_user_id;

        RETURN QUERY SELECT TRUE, v_used + 1, v_quota_limit, v_reset_at + INTERVAL '7 days';
    ELSE
        -- Quota exceeded
        RETURN QUERY SELECT FALSE, v_used, v_quota_limit, v_reset_at + INTERVAL '7 days';
    END IF;
END;
$$;


ALTER FUNCTION "public"."check_and_increment_rehearsal_quota"("p_user_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."check_and_increment_rehearsal_quota"("p_user_id" "uuid") IS 'Atomically checks and increments rehearsal quota to prevent race conditions';



CREATE OR REPLACE FUNCTION "public"."check_buddy_invite_limit"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_today_count INT;
BEGIN
  SELECT COUNT(*) INTO v_today_count
  FROM buddy_relationships
  WHERE inviter_id = NEW.inviter_id
    AND DATE(invited_at) = CURRENT_DATE;

  IF v_today_count >= 10 THEN
    RAISE EXCEPTION 'Daily buddy invite limit reached (10 per day)'
      USING ERRCODE = 'P0001';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."check_buddy_invite_limit"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_buddy_pair_badge"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_relationship buddy_relationships;
  v_days_together INT;
BEGIN
  -- Get relationship details
  SELECT * INTO v_relationship
  FROM buddy_relationships
  WHERE id = NEW.buddy_relationship_id;

  IF NOT FOUND OR v_relationship.status != 'accepted' THEN
    RETURN NEW;
  END IF;

  -- Calculate days together
  v_days_together := EXTRACT(DAY FROM (NOW() - v_relationship.accepted_at));

  -- Award badge if 7+ days together
  IF v_days_together >= 7 THEN
    -- Award to inviter
    INSERT INTO user_badges (user_id, badge_id)
    SELECT v_relationship.inviter_id, b.id
    FROM badges b WHERE b.code = 'buddy_pair'
    ON CONFLICT (user_id, badge_id) DO NOTHING;

    -- Award to invitee
    IF v_relationship.invitee_id IS NOT NULL THEN
      INSERT INTO user_badges (user_id, badge_id)
      SELECT v_relationship.invitee_id, b.id
      FROM badges b WHERE b.code = 'buddy_pair'
      ON CONFLICT (user_id, badge_id) DO NOTHING;
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."check_buddy_pair_badge"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_challenge_creation_rate_limit"("p_user_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE
    AS $$
DECLARE
    v_count INT;
    v_is_premium BOOLEAN;
BEGIN
    -- Check if user is premium
    SELECT (s.subscription_tier != 'free')
    INTO v_is_premium
    FROM subscriptions s
    WHERE s.user_id = p_user_id
    ORDER BY s.updated_at DESC
    LIMIT 1;

    -- If not premium, enforce 5 per day limit
    IF v_is_premium IS FALSE THEN
        SELECT COUNT(*)
        INTO v_count
        FROM challenges
        WHERE created_by = p_user_id
        AND created_at > NOW() - INTERVAL '1 day';

        RETURN v_count < 5;
    END IF;

    -- Premium users have no limit
    RETURN true;
END;
$$;


