CREATE OR REPLACE FUNCTION "public"."check_hug_limit"("p_sender_id" "uuid", "p_recipient_id" "uuid", "p_limit" integer DEFAULT 5) RETURNS TABLE("allowed" boolean, "count_today" integer, "remaining" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_count INT;
BEGIN
  -- Count hugs sent today from this sender to this recipient
  SELECT COUNT(*)
  INTO v_count
  FROM circle_hugs
  WHERE sender_id = p_sender_id
    AND recipient_id = p_recipient_id
    AND created_at::date = CURRENT_DATE;

  RETURN QUERY SELECT
    v_count < p_limit AS allowed,
    v_count AS count_today,
    GREATEST(0, p_limit - v_count) AS remaining;
END;
$$;


