CREATE OR REPLACE FUNCTION "public"."check_milestone_triggers"("p_user_id" "uuid", "p_streak" integer DEFAULT NULL::integer, "p_quest_count" integer DEFAULT NULL::integer, "p_exercise_count" integer DEFAULT NULL::integer, "p_new_level" integer DEFAULT NULL::integer, "p_badge_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("celebration_id" "uuid", "celebration_type" "text", "value" integer, "badge_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_celebration_id UUID;
  v_streak_milestones INT[] := ARRAY[7, 14, 30, 60, 100, 365];
  v_quest_milestones INT[] := ARRAY[10, 50, 100, 500];
  v_exercise_milestones INT[] := ARRAY[10, 50, 100];
BEGIN
  -- Check streak milestones
  IF p_streak IS NOT NULL AND p_streak = ANY(v_streak_milestones) THEN
    -- Only create if not already created for this milestone
    IF NOT EXISTS (
      SELECT 1 FROM celebration_events ce
      WHERE ce.user_id = p_user_id
        AND ce.celebration_type = 'streak_milestone'
        AND ce.value = p_streak
        AND ce.created_at > NOW() - INTERVAL '24 hours'
    ) THEN
      INSERT INTO celebration_events (user_id, celebration_type, value, shown_at)
      VALUES (p_user_id, 'streak_milestone', p_streak, NULL)
      RETURNING id INTO v_celebration_id;

      RETURN QUERY SELECT v_celebration_id, 'streak_milestone'::TEXT, p_streak, NULL::UUID;
    END IF;
  END IF;

  -- Check quest milestones
  IF p_quest_count IS NOT NULL AND p_quest_count = ANY(v_quest_milestones) THEN
    IF NOT EXISTS (
      SELECT 1 FROM celebration_events ce
      WHERE ce.user_id = p_user_id
        AND ce.celebration_type = 'quest_milestone'
        AND ce.value = p_quest_count
    ) THEN
      INSERT INTO celebration_events (user_id, celebration_type, value, shown_at)
      VALUES (p_user_id, 'quest_milestone', p_quest_count, NULL)
      RETURNING id INTO v_celebration_id;

      RETURN QUERY SELECT v_celebration_id, 'quest_milestone'::TEXT, p_quest_count, NULL::UUID;
    END IF;
  END IF;

  -- Check exercise milestones
  IF p_exercise_count IS NOT NULL AND p_exercise_count = ANY(v_exercise_milestones) THEN
    IF NOT EXISTS (
      SELECT 1 FROM celebration_events ce
      WHERE ce.user_id = p_user_id
        AND ce.celebration_type = 'exercise_milestone'
        AND ce.value = p_exercise_count
    ) THEN
      INSERT INTO celebration_events (user_id, celebration_type, value, shown_at)
      VALUES (p_user_id, 'exercise_milestone', p_exercise_count, NULL)
      RETURNING id INTO v_celebration_id;

      RETURN QUERY SELECT v_celebration_id, 'exercise_milestone'::TEXT, p_exercise_count, NULL::UUID;
    END IF;
  END IF;

  -- Check level up (always triggers a celebration)
  IF p_new_level IS NOT NULL THEN
    INSERT INTO celebration_events (user_id, celebration_type, value, shown_at)
    VALUES (p_user_id, 'level_up', p_new_level, NULL)
    RETURNING id INTO v_celebration_id;

    RETURN QUERY SELECT v_celebration_id, 'level_up'::TEXT, p_new_level, NULL::UUID;
  END IF;

  -- Check badge unlock (always triggers a celebration)
  IF p_badge_id IS NOT NULL THEN
    INSERT INTO celebration_events (user_id, celebration_type, value, badge_id, shown_at)
    VALUES (p_user_id, 'badge_unlock', 1, p_badge_id, NULL)
    RETURNING id INTO v_celebration_id;

    RETURN QUERY SELECT v_celebration_id, 'badge_unlock'::TEXT, 1, p_badge_id;
  END IF;
END;
$$;


ALTER FUNCTION "public"."check_milestone_triggers"("p_user_id" "uuid", "p_streak" integer, "p_quest_count" integer, "p_exercise_count" integer, "p_new_level" integer, "p_badge_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_rate_limit"("p_user_id" "uuid", "p_endpoint" "text", "p_window_start" timestamp with time zone, "p_max_requests" integer, "p_window_ms" integer) RETURNS TABLE("allowed" boolean, "remaining" integer, "reset_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_count INT;
  v_window_start TIMESTAMPTZ;
  v_reset_at TIMESTAMPTZ;
BEGIN
  SELECT request_count, window_start
  INTO v_count, v_window_start
  FROM rate_limits
  WHERE user_id = p_user_id AND endpoint = p_endpoint
  FOR UPDATE;

  IF NOT FOUND THEN
    INSERT INTO rate_limits (user_id, endpoint, request_count, window_start)
    VALUES (p_user_id, p_endpoint, 1, NOW())
    ON CONFLICT (user_id, endpoint) DO UPDATE
    SET request_count = 1, window_start = NOW();

    v_reset_at := NOW() + (p_window_ms || ' milliseconds')::interval;
    RETURN QUERY SELECT TRUE, p_max_requests - 1, v_reset_at;
    RETURN;
  END IF;

  IF v_window_start < p_window_start THEN
    UPDATE rate_limits
    SET request_count = 1, window_start = NOW()
    WHERE user_id = p_user_id AND endpoint = p_endpoint;

    v_reset_at := NOW() + (p_window_ms || ' milliseconds')::interval;
    RETURN QUERY SELECT TRUE, p_max_requests - 1, v_reset_at;
    RETURN;
  END IF;

  v_reset_at := v_window_start + (p_window_ms || ' milliseconds')::interval;

  IF v_count >= p_max_requests THEN
    RETURN QUERY SELECT FALSE, 0, v_reset_at;
    RETURN;
  END IF;

  UPDATE rate_limits
  SET request_count = v_count + 1
  WHERE user_id = p_user_id AND endpoint = p_endpoint;

  RETURN QUERY SELECT TRUE, p_max_requests - v_count - 1, v_reset_at;
END;
$$;


ALTER FUNCTION "public"."check_rate_limit"("p_user_id" "uuid", "p_endpoint" "text", "p_window_start" timestamp with time zone, "p_max_requests" integer, "p_window_ms" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_recent_notifications_batch"("p_checks" "jsonb") RETURNS TABLE("user_id" "uuid", "notification_type" "text", "recently_sent" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
BEGIN
  -- Create temp table for batch checking
  CREATE TEMP TABLE check_batch AS
  SELECT
    (item->>'user_id')::UUID AS user_id,
    item->>'notification_type' AS notification_type
  FROM jsonb_array_elements(p_checks) AS item;

  -- Check if notifications were sent recently (within 24 hours)
  RETURN QUERY
  SELECT
    cb.user_id,
    cb.notification_type,
    (MAX(pm.created_at) > NOW() - INTERVAL '24 hours')::BOOLEAN AS recently_sent
  FROM check_batch cb
  LEFT JOIN proactive_messages pm ON pm.user_id = cb.user_id
    AND pm.trigger_type = cb.notification_type
  GROUP BY cb.user_id, cb.notification_type;
END;
$$;


ALTER FUNCTION "public"."check_recent_notifications_batch"("p_checks" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_recovery_mode_eligibility"("p_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_result JSONB;
    v_current_in_recovery BOOLEAN;
    v_consecutive_low_days INT := 0;
    v_consecutive_good_days INT := 0;
    v_should_enter BOOLEAN := FALSE;
    v_should_exit BOOLEAN := FALSE;
    v_mood_record RECORD;
    v_threshold_days INT := 3;
BEGIN
    -- Get current recovery mode status
    SELECT recovery_mode_enabled INTO v_current_in_recovery
    FROM user_settings
    WHERE user_id = p_user_id;

    -- Count consecutive low mood days (score <= 2) from most recent
    FOR v_mood_record IN
        SELECT mood_score as score, DATE(created_at) as mood_date
        FROM moods
        WHERE user_id = p_user_id
        ORDER BY created_at DESC
        LIMIT 7
    LOOP
        IF v_mood_record.score <= 2 THEN
            v_consecutive_low_days := v_consecutive_low_days + 1;
        ELSE
            EXIT; -- Stop counting once we hit a non-low day
        END IF;
    END LOOP;

    -- Count consecutive good mood days (score >= 4) from most recent
    FOR v_mood_record IN
        SELECT mood_score as score, DATE(created_at) as mood_date
        FROM moods
        WHERE user_id = p_user_id
        ORDER BY created_at DESC
        LIMIT 7
    LOOP
        IF v_mood_record.score >= 4 THEN
            v_consecutive_good_days := v_consecutive_good_days + 1;
        ELSE
            EXIT; -- Stop counting once we hit a non-good day
        END IF;
    END LOOP;

    -- Determine if should enter or exit recovery mode
    IF NOT COALESCE(v_current_in_recovery, FALSE) AND v_consecutive_low_days >= v_threshold_days THEN
        v_should_enter := TRUE;
    ELSIF COALESCE(v_current_in_recovery, FALSE) AND v_consecutive_good_days >= v_threshold_days THEN
        v_should_exit := TRUE;
    END IF;

    -- Build result
    v_result := jsonb_build_object(
        'currentlyInRecovery', COALESCE(v_current_in_recovery, FALSE),
        'shouldEnter', v_should_enter,
        'shouldExit', v_should_exit,
        'consecutiveLowDays', v_consecutive_low_days,
        'consecutiveGoodDays', v_consecutive_good_days,
        'thresholdDays', v_threshold_days
    );

    RETURN v_result;
END;
$$;


