CREATE OR REPLACE FUNCTION "public"."check_signature_fetch_rate_limit"("p_user_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_recent_count INT;
BEGIN
  -- Allow max 10 fetches per minute
  SELECT COUNT(*)
  INTO v_recent_count
  FROM pattern_access_audit
  WHERE user_id = p_user_id
    AND access_type = 'signature_fetch'
    AND accessed_at > NOW() - INTERVAL '1 minute';

  RETURN v_recent_count < 10;
END;
$$;


