CREATE OR REPLACE FUNCTION "public"."claim_family_seat"("p_family_id" "uuid", "p_user_id" "uuid", "p_invited_email" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_admin_sub RECORD;
    v_existing_member RECORD;
    v_seats_available INT;
    v_result JSONB;
BEGIN
    -- Lock the admin subscription row for update to prevent race conditions
    SELECT *
    INTO v_admin_sub
    FROM subscriptions
    WHERE family_id = p_family_id
      AND is_family_admin = true
      AND status = 'active'
    FOR UPDATE;

    IF v_admin_sub IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Family subscription not found or inactive',
            'code', 'NO_ACTIVE_SUBSCRIPTION'
        );
    END IF;

    -- Calculate available seats
    v_seats_available := v_admin_sub.seats_total - v_admin_sub.seats_used;

    IF v_seats_available <= 0 THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'No seats available in this family plan',
            'code', 'NO_SEATS_AVAILABLE',
            'seats_used', v_admin_sub.seats_used,
            'seats_total', v_admin_sub.seats_total
        );
    END IF;

    -- Check if user is already an active member
    SELECT *
    INTO v_existing_member
    FROM family_members
    WHERE family_id = p_family_id
      AND user_id = p_user_id
      AND status = 'active';

    IF v_existing_member IS NOT NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'User is already an active member of this family',
            'code', 'ALREADY_MEMBER'
        );
    END IF;

    -- Atomically increment seats_used
    UPDATE subscriptions
    SET seats_used = seats_used + 1,
        updated_at = now()
    WHERE id = v_admin_sub.id
      AND seats_used < seats_total;  -- Double-check constraint

    IF NOT FOUND THEN
        -- Race condition occurred - another request claimed the last seat
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Seat was claimed by another request',
            'code', 'SEAT_RACE_CONDITION'
        );
    END IF;

    -- Check for existing inactive member to reactivate
    SELECT *
    INTO v_existing_member
    FROM family_members
    WHERE family_id = p_family_id
      AND user_id = p_user_id;

    IF v_existing_member IS NOT NULL THEN
        -- Reactivate existing membership
        UPDATE family_members
        SET status = 'active',
            joined_at = now(),
            removed_at = NULL
        WHERE id = v_existing_member.id;
    ELSE
        -- Create new family member
        INSERT INTO family_members (family_id, user_id, invited_email, status, joined_at)
        VALUES (p_family_id, p_user_id, p_invited_email, 'active', now());
    END IF;

    -- Log the event
    INSERT INTO billing_events (event_type, user_id, family_id, payload)
    VALUES (
        'family_seat_claimed',
        p_user_id,
        p_family_id,
        jsonb_build_object(
            'seats_used', v_admin_sub.seats_used + 1,
            'seats_total', v_admin_sub.seats_total,
            'admin_subscription_id', v_admin_sub.id
        )
    );

    RETURN jsonb_build_object(
        'success', true,
        'message', 'Seat claimed successfully',
        'seats_used', v_admin_sub.seats_used + 1,
        'seats_total', v_admin_sub.seats_total,
        'admin_subscription_id', v_admin_sub.id
    );
END;
$$;


ALTER FUNCTION "public"."claim_family_seat"("p_family_id" "uuid", "p_user_id" "uuid", "p_invited_email" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_listener_for_session"("p_session_id" "uuid", "p_topic_tags" "text"[] DEFAULT NULL::"text"[], "p_preferred_language" "text" DEFAULT 'en'::"text", "p_session_type" "text" DEFAULT 'quick'::"text", "p_user_timezone" "text" DEFAULT 'UTC'::"text") RETURNS TABLE("listener_id" "uuid", "user_id" "uuid", "display_name" "text", "average_rating" numeric, "total_sessions" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_listener RECORD;
    v_day_of_week INTEGER;
    v_current_time TIME;
    v_utc_offset INTERVAL;
BEGIN
    -- Calculate the current time in the listener's timezone context
    -- For simplicity, we convert to UTC and compare against availability
    v_day_of_week := EXTRACT(DOW FROM NOW() AT TIME ZONE p_user_timezone);
    v_current_time := (NOW() AT TIME ZONE p_user_timezone)::TIME;

    -- Find and lock an available listener atomically
    -- FOR UPDATE SKIP LOCKED prevents race conditions - if another transaction
    -- is already processing a listener, we skip to the next one
    FOR v_listener IN
        SELECT l.id, l.user_id, l.display_name, l.average_rating, l.total_sessions
        FROM listeners l
        WHERE l.status = 'active'
        AND l.is_available = true
        -- Check topic specialization match if provided
        AND (p_topic_tags IS NULL OR p_topic_tags = '{}' OR l.specializations && p_topic_tags)
        -- Check language preference
        AND p_preferred_language = ANY(l.languages)
        -- Check crisis bridge capability if needed
        AND (p_session_type != 'crisis_bridge' OR l.accepts_crisis_bridge = true)
        -- Check availability schedule
        AND EXISTS (
            SELECT 1 FROM listener_availability la
            WHERE la.listener_id = l.id
            AND la.is_active = true
            AND la.day_of_week = v_day_of_week
            AND v_current_time BETWEEN la.start_time AND la.end_time
        )
        -- Check no active sessions
        AND NOT EXISTS (
            SELECT 1 FROM support_sessions ss
            WHERE ss.listener_id = l.id
            AND ss.status IN ('matched', 'active')
        )
        ORDER BY l.average_rating DESC NULLS LAST, l.total_sessions ASC
        FOR UPDATE OF l SKIP LOCKED
        LIMIT 1
    LOOP
        -- Found an available listener, claim them for this session
        UPDATE support_sessions
        SET
            listener_id = v_listener.id,
            status = 'matched',
            matched_at = NOW()
        WHERE id = p_session_id
        AND status = 'pending';  -- Only update if still pending

        IF FOUND THEN
            -- Return the matched listener info
            RETURN QUERY SELECT
                v_listener.id,
                v_listener.user_id,
                v_listener.display_name,
                v_listener.average_rating,
                v_listener.total_sessions;
            RETURN;
        END IF;
    END LOOP;

    -- No listener found
    RETURN;
END;
$$;


ALTER FUNCTION "public"."claim_listener_for_session"("p_session_id" "uuid", "p_topic_tags" "text"[], "p_preferred_language" "text", "p_session_type" "text", "p_user_timezone" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."claim_listener_for_session"("p_session_id" "uuid", "p_topic_tags" "text"[], "p_preferred_language" "text", "p_session_type" "text", "p_user_timezone" "text") IS 'Atomically claims an available listener for a session using row-level locking';



CREATE OR REPLACE FUNCTION "public"."cleanup_expired_intents"("batch_limit" integer DEFAULT 1000) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  deleted_count INT;
BEGIN
  WITH to_delete AS (
    SELECT id FROM daily_intents
    WHERE expires_at < NOW()
    LIMIT batch_limit
  )
  DELETE FROM daily_intents
  WHERE id IN (SELECT id FROM to_delete);

  GET DIAGNOSTICS deleted_count = ROW_COUNT;
  RETURN deleted_count;
END;
$$;


ALTER FUNCTION "public"."cleanup_expired_intents"("batch_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cleanup_expired_intents"("batch_limit" integer) IS 'Deletes expired daily intents (call via cron or manually)';



CREATE OR REPLACE FUNCTION "public"."cleanup_expired_memories"("batch_limit" integer DEFAULT 1000) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  deleted_count INT;
BEGIN
  -- Delete in batches to prevent locking issues and DOS
  WITH to_delete AS (
    SELECT id FROM memory_fragments
    WHERE expires_at IS NOT NULL AND expires_at < NOW()
    LIMIT batch_limit
  )
  DELETE FROM memory_fragments
  WHERE id IN (SELECT id FROM to_delete);

  GET DIAGNOSTICS deleted_count = ROW_COUNT;
  RETURN deleted_count;
END;
$$;


ALTER FUNCTION "public"."cleanup_expired_memories"("batch_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cleanup_expired_memories"("batch_limit" integer) IS 'Removes expired memory fragments in batches (default 1000). Call repeatedly if more need cleanup.';



