BEGIN
  -- Atomically decrement supply count and return new value
  UPDATE medications
  SET
    supply_count = supply_count - 1,
    updated_at = now()
  WHERE id = med_id
    AND user_id = user_id
    AND supply_count > 0
    AND is_active = true
  RETURNING supply_count INTO updated_count;

  RETURN COALESCE(updated_count, 0);
