CREATE OR REPLACE FUNCTION "public"."end_voice_session"("p_session_id" "uuid", "p_duration_seconds" integer, "p_messages_count" integer DEFAULT 0, "p_was_quota_limited" boolean DEFAULT false) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_user_id UUID;
    v_duration_minutes FLOAT;
    v_period_start DATE;
BEGIN
    -- Get user ID from session
    SELECT user_id INTO v_user_id
    FROM voice_sessions
    WHERE id = p_session_id;

    IF v_user_id IS NULL THEN
        RETURN;
    END IF;

    -- Calculate minutes
    v_duration_minutes := p_duration_seconds / 60.0;
    v_period_start := DATE_TRUNC('month', NOW())::DATE;

    -- Update session record
    UPDATE voice_sessions
    SET
        ended_at = NOW(),
        duration_seconds = p_duration_seconds,
        messages_count = p_messages_count,
        was_quota_limited = p_was_quota_limited
    WHERE id = p_session_id;

    -- Increment usage
    PERFORM increment_voice_usage(v_user_id, v_duration_minutes, v_period_start);
END;
$$;


ALTER FUNCTION "public"."end_voice_session"("p_session_id" "uuid", "p_duration_seconds" integer, "p_messages_count" integer, "p_was_quota_limited" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_hug_limit"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_count INT;
BEGIN
  -- Count hugs sent today from this sender to this recipient
  SELECT COUNT(*) INTO v_count
  FROM circle_hugs
  WHERE sender_id = NEW.sender_id
    AND recipient_id = NEW.recipient_id
    AND created_at::date = CURRENT_DATE;

  IF v_count >= 5 THEN
    RAISE EXCEPTION 'Daily hug limit reached (5 per recipient per day)'
      USING ERRCODE = 'P0001';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."enforce_hug_limit"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."enforce_hug_limit"() IS 'Trigger function that enforces 5 hugs/day limit per sender-recipient pair atomically';



CREATE OR REPLACE FUNCTION "public"."enforce_memory_limit"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  memory_count INT;
BEGIN
  -- Count active memories for this user with FOR UPDATE lock to prevent race conditions
  -- This ensures concurrent inserts don't bypass the limit
  SELECT COUNT(*) INTO memory_count
  FROM companion_memory
  WHERE user_id = NEW.user_id AND deleted_at IS NULL
  FOR UPDATE;

  -- Block if limit reached
  IF memory_count >= 20 THEN
    RAISE EXCEPTION 'Memory limit reached (20/20). Delete a memory before adding a new one.';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."enforce_memory_limit"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_profiles_column_restrictions"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- Service role can update any column (used by Edge Functions)
  IF current_setting('role', true) = 'service_role' THEN
    RETURN NEW;
  END IF;

  -- Authenticated users can only update safe columns
  -- FIXED: Remove SELECT wrapper that caused "argument of AND must not return a set" error
  IF auth.role() = 'authenticated' THEN
    -- Block updates to revenue-critical and quota columns
    IF NEW.subscription_tier IS DISTINCT FROM OLD.subscription_tier THEN
      RAISE EXCEPTION 'Insufficient privileges to modify subscription_tier';
    END IF;

    IF NEW.daily_ai_quota IS DISTINCT FROM OLD.daily_ai_quota THEN
      RAISE EXCEPTION 'Insufficient privileges to modify daily_ai_quota';
    END IF;

    IF NEW.daily_ai_used IS DISTINCT FROM OLD.daily_ai_used THEN
      RAISE EXCEPTION 'Insufficient privileges to modify daily_ai_used';
    END IF;

    IF NEW.quota_reset_at IS DISTINCT FROM OLD.quota_reset_at THEN
      RAISE EXCEPTION 'Insufficient privileges to modify quota_reset_at';
    END IF;

    IF NEW.premium_badge IS DISTINCT FROM OLD.premium_badge THEN
      RAISE EXCEPTION 'Insufficient privileges to modify premium_badge';
    END IF;

    -- Allow updates to these safe columns
    -- - handle
    -- - display_name
    -- - timezone
    -- - typical_active_hour (for smart notifications)
    -- - last_session_at, session_count, last_absence_days (for re-engagement tracking)
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."enforce_profiles_column_restrictions"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."enforce_profiles_column_restrictions"() IS 'Trigger function to restrict profile updates to safe columns for authenticated users (fixed auth.role() check)';



CREATE OR REPLACE FUNCTION "public"."enforce_profiles_insert_defaults"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- Only apply restrictions to authenticated users creating their own profiles
  -- Service role and admin operations bypass this
  IF (SELECT auth.role() = 'authenticated') THEN
    -- Force default values for revenue-critical columns
    -- These can only be set by Edge Functions/service role after purchase verification
    NEW.subscription_tier := 'free';
    NEW.daily_ai_quota := 10;        -- Free tier default
    NEW.daily_ai_used := 0;
    NEW.quota_reset_at := NOW();
    NEW.premium_badge := FALSE;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."enforce_profiles_insert_defaults"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."enforce_profiles_insert_defaults"() IS 'Enforce INSERT defaults: users cannot set subscription_tier, quota, premium_badge when creating profiles. Service role can override.';



CREATE OR REPLACE FUNCTION "public"."enroll_in_program"("p_program_id" "uuid", "p_preferred_time" time without time zone DEFAULT '09:00:00'::time without time zone) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id UUID := auth.uid();
  v_enrollment_id UUID;
  v_is_premium BOOLEAN;
  v_program_premium BOOLEAN;
  v_has_active BOOLEAN;
BEGIN
  -- Ensure user is authenticated
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  -- Check if user has premium (if program requires it)
  SELECT COALESCE(subscription_tier = 'premium', FALSE) INTO v_is_premium
  FROM profiles WHERE id = v_user_id;

  SELECT premium_only INTO v_program_premium
  FROM programs WHERE id = p_program_id AND is_active = TRUE;

  IF v_program_premium IS NULL THEN
    RAISE EXCEPTION 'Program not found or inactive';
  END IF;

  IF v_program_premium AND NOT COALESCE(v_is_premium, FALSE) THEN
    RAISE EXCEPTION 'Premium subscription required for this program';
  END IF;

  -- Check for existing active enrollment (only one active at a time)
  SELECT EXISTS(
    SELECT 1 FROM program_enrollments
    WHERE user_id = v_user_id AND status = 'active'
  ) INTO v_has_active;

  IF v_has_active THEN
    RAISE EXCEPTION 'Already enrolled in an active program. Complete or pause current program first.';
  END IF;

  -- Create enrollment
  INSERT INTO program_enrollments (
    user_id, program_id, preferred_time_local
  ) VALUES (
    v_user_id, p_program_id, p_preferred_time
  ) RETURNING id INTO v_enrollment_id;

  -- Create day 1 progress entry
  INSERT INTO program_day_progress (enrollment_id, day_number, status)
  VALUES (v_enrollment_id, 1, 'pending');

  RETURN v_enrollment_id;
END;
$$;


ALTER FUNCTION "public"."enroll_in_program"("p_program_id" "uuid", "p_preferred_time" time without time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ensure_profile_exists"("p_user_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_email TEXT;
  v_user_metadata JSONB;
  random_handle TEXT;
BEGIN
  -- Check if profile already exists
  IF EXISTS (SELECT 1 FROM profiles WHERE id = p_user_id) THEN
    RETURN;
  END IF;

  -- Get user info from auth.users
  SELECT email, raw_user_meta_data
  INTO v_user_email, v_user_metadata
  FROM auth.users
  WHERE id = p_user_id;

  -- If user doesn't exist in auth.users, we can't create profile
  IF NOT FOUND THEN
    RAISE EXCEPTION 'User % does not exist in auth.users', p_user_id;
  END IF;

  -- Generate random handle
  random_handle := 'user_' || substr(md5(random()::text), 1, 8);

  -- Create profile with defaults
  INSERT INTO profiles (
    id,
    handle,
    display_name,
    email,
    daily_ai_used,
    daily_ai_quota,
    quota_reset_at
  )
  VALUES (
    p_user_id,
    random_handle,
    COALESCE(v_user_metadata->>'full_name', 'MindFriend User'),
    v_user_email,
    0,  -- Start with 0 quota used
    10, -- Default free tier quota
    NOW() -- Reset time is now
  );

  -- Create settings if missing
  INSERT INTO user_settings (user_id)
  VALUES (p_user_id)
  ON CONFLICT (user_id) DO NOTHING;

  -- Create stats if missing
  INSERT INTO user_stats (user_id)
  VALUES (p_user_id)
  ON CONFLICT (user_id) DO NOTHING;

  -- Log this for monitoring
  RAISE NOTICE 'Created missing profile for user %', p_user_id;
END;
$$;


ALTER FUNCTION "public"."ensure_profile_exists"("p_user_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."ensure_profile_exists"("p_user_id" "uuid") IS 'Creates profile, settings, and stats if missing - defensive fallback';



CREATE OR REPLACE FUNCTION "public"."evaluate_recovery_mode_for_user"("p_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_current_state BOOLEAN;
    v_entered_at TIMESTAMPTZ;
    v_reason TEXT;
    v_consecutive_low_days INT := 0;
    v_consecutive_good_days INT := 0;
    v_mood_record RECORD;
    v_result JSONB;
BEGIN
    -- Get current recovery mode state
    SELECT
        recovery_mode_active,
        recovery_mode_entered_at,
        recovery_mode_reason
    INTO v_current_state, v_entered_at, v_reason
    FROM user_settings
    WHERE user_id = p_user_id;

    -- Count consecutive low mood days (score <= 2) from most recent
    FOR v_mood_record IN
        SELECT score, DATE(logged_at) as mood_date
        FROM moods
        WHERE user_id = p_user_id
        ORDER BY logged_at DESC
        LIMIT 7
    LOOP
        IF v_mood_record.score <= 2 THEN
            v_consecutive_low_days := v_consecutive_low_days + 1;
        ELSE
            EXIT; -- Break on first non-low day
        END IF;
    END LOOP;

    -- Count consecutive good mood days (score >= 4) from most recent
    FOR v_mood_record IN
        SELECT score, DATE(logged_at) as mood_date
        FROM moods
        WHERE user_id = p_user_id
        ORDER BY logged_at DESC
        LIMIT 7
    LOOP
        IF v_mood_record.score >= 4 THEN
            v_consecutive_good_days := v_consecutive_good_days + 1;
        ELSE
            EXIT; -- Break on first non-good day
        END IF;
    END LOOP;

    -- Decision logic
    IF NOT v_current_state THEN
        -- Not in recovery mode - check if we should auto-enter
        IF v_consecutive_low_days >= 3 THEN
            -- Auto-enter recovery mode
            UPDATE user_settings
            SET
                recovery_mode_active = TRUE,
                recovery_mode_entered_at = NOW(),
                recovery_mode_reason = 'auto_consecutive_low_mood'
            WHERE user_id = p_user_id;

            v_result := jsonb_build_object(
                'action', 'entered',
                'reason', 'auto_consecutive_low_mood',
                'consecutive_low_days', v_consecutive_low_days
            );
        ELSE
            v_result := jsonb_build_object(
                'action', 'none',
                'reason', 'no_trigger',
                'consecutive_low_days', v_consecutive_low_days
            );
        END IF;
    ELSE
        -- In recovery mode - check if we should auto-exit
        -- Auto-exit after 7 days OR 3+ consecutive good mood days
        IF v_entered_at IS NOT NULL AND (NOW() - v_entered_at) > INTERVAL '7 days' THEN
            -- Auto-exit: exceeded max duration
            UPDATE user_settings
            SET
                recovery_mode_active = FALSE,
                recovery_mode_entered_at = NULL,
                recovery_mode_reason = NULL
            WHERE user_id = p_user_id;

            v_result := jsonb_build_object(
                'action', 'exited',
                'reason', 'max_duration_7_days'
            );
        ELSIF v_consecutive_good_days >= 3 THEN
            -- Auto-exit: mood improved
            UPDATE user_settings
            SET
                recovery_mode_active = FALSE,
                recovery_mode_entered_at = NULL,
                recovery_mode_reason = NULL
            WHERE user_id = p_user_id;

            v_result := jsonb_build_object(
                'action', 'exited',
                'reason', 'mood_improved',
                'consecutive_good_days', v_consecutive_good_days
            );
        ELSE
            v_result := jsonb_build_object(
                'action', 'none',
                'reason', 'still_recovering',
                'days_in_recovery', EXTRACT(DAY FROM NOW() - v_entered_at)::INT,
                'consecutive_good_days', v_consecutive_good_days
            );
        END IF;
    END IF;

    RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."evaluate_recovery_mode_for_user"("p_user_id" "uuid") OWNER TO "postgres";


