CREATE OR REPLACE FUNCTION "public"."fail_recovery_quest"("p_user_id" "uuid", "p_attempt_id" "uuid") RETURNS TABLE("success" boolean, "attempts_remaining" integer, "can_retry" boolean, "error_message" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_attempt RECORD;
  v_stats RECORD;
BEGIN
  -- Security check
  IF auth.uid() IS NOT NULL AND auth.uid() != p_user_id THEN
    RAISE EXCEPTION 'Unauthorized: cannot fail recovery for another user';
  END IF;

  -- Get the recovery attempt
  SELECT * INTO v_attempt
  FROM recovery_quest_attempts
  WHERE id = p_attempt_id AND user_id = p_user_id;

  IF v_attempt IS NULL THEN
    RETURN QUERY SELECT FALSE, 0, FALSE, 'Recovery attempt not found'::TEXT;
    RETURN;
  END IF;

  IF v_attempt.status != 'in_progress' THEN
    RETURN QUERY SELECT FALSE, 0, FALSE, ('Recovery attempt status is ' || v_attempt.status)::TEXT;
    RETURN;
  END IF;

  -- Mark attempt as failed
  UPDATE recovery_quest_attempts SET
    status = 'failed'
  WHERE id = p_attempt_id;

  -- Get updated stats
  SELECT * INTO v_stats FROM user_stats WHERE user_id = p_user_id;

  RETURN QUERY SELECT
    TRUE,
    v_stats.recovery_attempts_remaining,
    (v_stats.recovery_attempts_remaining > 0 AND v_stats.recovery_quest_expires_at > NOW()),
    NULL::TEXT;
END;
$$;


ALTER FUNCTION "public"."fail_recovery_quest"("p_user_id" "uuid", "p_attempt_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."find_milestone_approaching_users"() RETURNS TABLE("user_id" "uuid", "current_streak_days" integer, "next_milestone" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  milestones INT[] := ARRAY[7, 14, 30, 60, 100, 365];
BEGIN
  RETURN QUERY
  SELECT
    p.id AS user_id,
    p.current_streak_days,
    m AS next_milestone
  FROM profiles p
  JOIN user_settings us ON us.user_id = p.id
  CROSS JOIN UNNEST(milestones) AS m
  WHERE
    p.current_streak_days = m - 1  -- One day away from milestone
    -- No milestone message sent today
    AND NOT EXISTS (
      SELECT 1 FROM proactive_messages pm
      WHERE pm.user_id = p.id
        AND pm.trigger_type = 'milestone_approach'
        AND pm.created_at > NOW() - INTERVAL '24 hours'
    )
    -- Proactive enabled
    AND us.proactive_enabled = TRUE
    AND 'milestone_approach' = ANY(us.proactive_types_enabled);
END;
$$;


ALTER FUNCTION "public"."find_milestone_approaching_users"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."find_milestone_approaching_users"() IS 'Find users 1 day away from streak milestones (7, 14, 30, 60, 100, 365)';



CREATE OR REPLACE FUNCTION "public"."find_mood_decline_users"("p_threshold" integer DEFAULT 2, "p_consecutive_days" integer DEFAULT 2) RETURNS TABLE("user_id" "uuid", "avg_mood" double precision, "consecutive_days" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  WITH recent_moods AS (
    SELECT
      m.user_id,
      m.mood_score,
      m.local_date,
      ROW_NUMBER() OVER (PARTITION BY m.user_id ORDER BY m.local_date DESC) AS rn
    FROM moods m
    WHERE m.created_at > NOW() - INTERVAL '7 days'
  ),
  low_mood_streaks AS (
    SELECT
      rm.user_id,
      COUNT(*) AS consecutive_low_days,
      AVG(rm.mood_score) AS avg_mood
    FROM recent_moods rm
    WHERE rm.rn <= p_consecutive_days
      AND rm.mood_score <= p_threshold
    GROUP BY rm.user_id
    HAVING COUNT(*) >= p_consecutive_days
  )
  SELECT
    lms.user_id,
    lms.avg_mood::FLOAT,
    lms.consecutive_low_days::INT
  FROM low_mood_streaks lms
  -- Exclude users who already received a mood_decline message in last 24h
  WHERE NOT EXISTS (
    SELECT 1 FROM proactive_messages pm
    WHERE pm.user_id = lms.user_id
      AND pm.trigger_type = 'mood_decline'
      AND pm.created_at > NOW() - INTERVAL '24 hours'
  )
  -- Only users with proactive enabled
  AND EXISTS (
    SELECT 1 FROM user_settings us
    WHERE us.user_id = lms.user_id
      AND us.proactive_enabled = TRUE
      AND 'mood_decline' = ANY(us.proactive_types_enabled)
  );
END;
$$;


ALTER FUNCTION "public"."find_mood_decline_users"("p_threshold" integer, "p_consecutive_days" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."find_mood_decline_users"("p_threshold" integer, "p_consecutive_days" integer) IS 'Find users with consecutive low mood days for proactive outreach';



CREATE OR REPLACE FUNCTION "public"."find_reengagement_users"("p_days_inactive" integer DEFAULT 3) RETURNS TABLE("user_id" "uuid", "days_inactive" integer, "last_activity_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    ues.user_id,
    EXTRACT(EPOCH FROM NOW() - ues.last_activity_at)::INT / 86400 AS days_inactive,
    ues.last_activity_at
  FROM user_engagement_states ues
  JOIN user_settings us ON us.user_id = ues.user_id
  WHERE
    ues.current_state IN ('DRIFTING', 'LAPSED')
    AND EXTRACT(EPOCH FROM NOW() - ues.last_activity_at) / 86400 >= p_days_inactive
    -- Only send on specific days: 3, 7, 14 days
    AND EXTRACT(EPOCH FROM NOW() - ues.last_activity_at)::INT / 86400 IN (3, 7, 14)
    -- No reengagement message sent recently
    AND NOT EXISTS (
      SELECT 1 FROM proactive_messages pm
      WHERE pm.user_id = ues.user_id
        AND pm.trigger_type = 'reengagement'
        AND pm.created_at > NOW() - INTERVAL '3 days'
    )
    -- Proactive enabled
    AND us.proactive_enabled = TRUE
    AND 'reengagement' = ANY(us.proactive_types_enabled)
    -- Not too many ignored messages
    AND ues.proactive_ignore_count < 3;
END;
$$;


ALTER FUNCTION "public"."find_reengagement_users"("p_days_inactive" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."find_reengagement_users"("p_days_inactive" integer) IS 'Find inactive users for re-engagement (day 3, 7, 14)';



CREATE OR REPLACE FUNCTION "public"."find_streak_risk_users"("p_min_streak" integer DEFAULT 3) RETURNS TABLE("user_id" "uuid", "current_streak_days" integer, "timezone" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    p.id AS user_id,
    p.current_streak_days,
    COALESCE(us.timezone, 'UTC') AS timezone
  FROM profiles p
  JOIN user_settings us ON us.user_id = p.id
  WHERE
    p.current_streak_days >= p_min_streak
    -- It's past 6 PM local time
    AND EXTRACT(HOUR FROM NOW() AT TIME ZONE COALESCE(us.timezone, 'UTC')) >= 18
    -- No activity today
    AND NOT EXISTS (
      SELECT 1 FROM quests q
      WHERE q.user_id = p.id
        AND q.status = 'completed'
        AND q.local_date = (NOW() AT TIME ZONE COALESCE(us.timezone, 'UTC'))::date::text
    )
    -- No streak_risk message sent today
    AND NOT EXISTS (
      SELECT 1 FROM proactive_messages pm
      WHERE pm.user_id = p.id
        AND pm.trigger_type = 'streak_risk'
        AND pm.created_at > NOW() - INTERVAL '24 hours'
    )
    -- Proactive enabled
    AND us.proactive_enabled = TRUE
    AND 'streak_risk' = ANY(us.proactive_types_enabled);
END;
$$;


ALTER FUNCTION "public"."find_streak_risk_users"("p_min_streak" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."find_streak_risk_users"("p_min_streak" integer) IS 'Find users with streaks at risk (no activity today, past 6 PM)';



