    c.id,
    c.circle_id,
    c.created_by,
    c.challenge_type,
    c.title,
    c.description,
    c.target_exercise_id,
    c.starts_at,
    c.ends_at,
    c.created_at
  FROM circle_challenges c
  WHERE c.circle_id = p_circle_id
    AND c.starts_at <= NOW()
