CREATE OR REPLACE FUNCTION "public"."get_active_circle_rooms"() RETURNS TABLE("id" "uuid", "circle_id" "uuid", "circle_name" "text", "created_by" "uuid", "creator_name" "text", "activity_type" "text", "title" "text", "duration_minutes" integer, "started_at" timestamp with time zone, "ends_at" timestamp with time zone, "participant_count" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    clr.id,
    clr.circle_id,
    c.name AS circle_name,
    clr.created_by,
    p.display_name AS creator_name,
    clr.activity_type,
    clr.title,
    clr.duration_minutes,
    clr.started_at,
    clr.ends_at,
    COALESCE(part.cnt, 0) AS participant_count
  FROM circle_live_rooms clr
  JOIN circles c ON c.id = clr.circle_id
  JOIN profiles p ON p.id = clr.created_by
  JOIN circle_members cm ON cm.circle_id = clr.circle_id AND cm.user_id = auth.uid()
  LEFT JOIN (
    SELECT room_id, COUNT(*) AS cnt
    FROM circle_room_participants
    WHERE left_at IS NULL
    GROUP BY room_id
  ) part ON part.room_id = clr.id
  WHERE clr.status = 'active'
    AND clr.ends_at > NOW()
  ORDER BY clr.started_at DESC;
END;
$$;


