CREATE OR REPLACE FUNCTION "public"."get_active_partner_id"() RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    partner_id UUID;
BEGIN
    SELECT 
        CASE 
            WHEN user_id_1 = auth.uid() THEN user_id_2
            WHEN user_id_2 = auth.uid() THEN user_id_1
        END
    INTO partner_id
    FROM partner_links
    WHERE status = 'active'
    AND (user_id_1 = auth.uid() OR user_id_2 = auth.uid())
    LIMIT 1;
    
    RETURN partner_id;
END;
$$;


