CREATE OR REPLACE FUNCTION "public"."get_active_partner_link_id"() RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    link_id UUID;
BEGIN
    SELECT id
    INTO link_id
    FROM partner_links
    WHERE status = 'active'
    AND (user_id_1 = auth.uid() OR user_id_2 = auth.uid())
    AND user_id_2 IS NOT NULL
    LIMIT 1;
    
    RETURN link_id;
END;
$$;


