CREATE OR REPLACE FUNCTION "public"."get_challenge_leaderboard"("p_challenge_id" "uuid", "p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0) RETURNS TABLE("rank_position" integer, "user_id" "uuid", "user_display_name" "text", "user_avatar_url" "text", "current_progress" integer, "joined_at" timestamp with time zone, "show_on_leaderboard" boolean, "is_tied" boolean)
    LANGUAGE "plpgsql" STABLE
    AS $$
DECLARE
    v_tie_threshold INTERVAL := INTERVAL '1 second';
BEGIN
    RETURN QUERY
    WITH ranked_participants AS (
        SELECT
            cp.user_id,
            p.display_name,
            p.avatar_url,
            cp.current_progress,
            cp.joined_at,
            cp.show_on_leaderboard,
            ROW_NUMBER() OVER (
                ORDER BY cp.current_progress DESC, cp.joined_at ASC
            ) as rn,
            RANK() OVER (
                ORDER BY cp.current_progress DESC, 
                CASE 
                    WHEN LAG(cp.joined_at) OVER (ORDER BY cp.current_progress DESC, cp.joined_at ASC) 
                        IS NULL THEN cp.joined_at
                    WHEN LAG(cp.joined_at) OVER (ORDER BY cp.current_progress DESC, cp.joined_at ASC) 
                        > (cp.joined_at - v_tie_threshold) THEN cp.joined_at
                    ELSE LAG(cp.joined_at) OVER (ORDER BY cp.current_progress DESC, cp.joined_at ASC)
                END
            ) as tie_rank
        FROM challenge_participants cp
        JOIN profiles p ON cp.user_id = p.id
        WHERE cp.challenge_id = p_challenge_id
        AND cp.show_on_leaderboard = true
        ORDER BY cp.current_progress DESC, cp.joined_at ASC
    )
    SELECT
        tie_rank::INT,
        user_id,
        user_display_name,
        user_avatar_url,
        current_progress,
        joined_at,
        show_on_leaderboard,
        (LAG(current_progress) OVER (ORDER BY rn) = current_progress 
         OR LEAD(current_progress) OVER (ORDER BY rn) = current_progress)::BOOLEAN
    FROM ranked_participants
    WHERE rn > p_offset
    LIMIT p_limit;
END;
$$;


ALTER FUNCTION "public"."get_challenge_leaderboard"("p_challenge_id" "uuid", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_circle_presence"("p_circle_id" "uuid") RETURNS TABLE("user_id" "uuid", "display_name" "text", "status" "text", "last_seen_at" timestamp with time zone, "current_activity" "text", "is_online" boolean, "is_recently_active" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    up.user_id,
    p.display_name,
    up.status,
    up.last_seen_at,
    up.current_activity,
    (up.status = 'online' AND up.last_seen_at > NOW() - INTERVAL '2 minutes') AS is_online,
    (up.last_seen_at > NOW() - INTERVAL '15 minutes') AS is_recently_active
  FROM user_presence up
  JOIN profiles p ON p.id = up.user_id
  JOIN circle_members cm ON cm.user_id = up.user_id AND cm.circle_id = p_circle_id
  JOIN user_settings us ON us.user_id = up.user_id AND us.show_presence = TRUE
  WHERE up.last_seen_at > NOW() - INTERVAL '15 minutes'
  ORDER BY up.last_seen_at DESC;
END;
$$;


ALTER FUNCTION "public"."get_circle_presence"("p_circle_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_content_analytics"("p_content_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    result JSONB;
    creator_user_id UUID;
BEGIN
    -- Verify ownership
    SELECT c.user_id INTO creator_user_id
    FROM creators c
    JOIN creator_content cc ON cc.creator_id = c.id
    WHERE cc.id = p_content_id;

    IF creator_user_id != auth.uid() THEN
        RAISE EXCEPTION 'Not authorized to view this content''s analytics';
    END IF;

    SELECT jsonb_build_object(
        'totalPlays', COALESCE(cc.play_count, 0),
        'uniqueListeners', COALESCE(cc.unique_listeners, 0),
        'completionRate', COALESCE(cc.average_completion_rate, 0),
        'averageRating', cc.average_rating,
        'ratingCount', COALESCE(cc.rating_count, 0),
        'totalMinutesPlayed', COALESCE(cc.total_minutes_played, 0),
        'dailyPlays', (
            SELECT jsonb_agg(jsonb_build_object('date', engagement_date, 'count', cnt))
            FROM (
                SELECT engagement_date, COUNT(*) as cnt
                FROM content_engagement
                WHERE content_id = p_content_id
                AND engagement_date >= CURRENT_DATE - INTERVAL '30 days'
                GROUP BY engagement_date
                ORDER BY engagement_date
            ) daily
        )
    ) INTO result
    FROM creator_content cc
    WHERE cc.id = p_content_id;

    RETURN result;
END;
$$;


ALTER FUNCTION "public"."get_content_analytics"("p_content_id" "uuid") OWNER TO "postgres";


