CREATE OR REPLACE FUNCTION "public"."get_creative_quota"() RETURNS TABLE("ai_art_count" integer, "ai_art_limit" integer, "voice_minutes_used" integer, "voice_minutes_limit" integer, "is_premium" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_user_id UUID := auth.uid();
    v_today DATE := CURRENT_DATE;
    v_is_premium BOOLEAN;
BEGIN
    -- Check if user is premium
    SELECT EXISTS(
        SELECT 1 FROM subscriptions
        WHERE user_id = v_user_id
        AND status = 'active'
    ) INTO v_is_premium;

    -- Get or create today's quota
    INSERT INTO creative_quota_usage (user_id, date, ai_art_count, voice_minutes_used)
    VALUES (v_user_id, v_today, 0, 0)
    ON CONFLICT (user_id, date) DO NOTHING;

    -- Return quota info
    -- Free tier: 1 AI art per day (stricter paywall)
    -- Premium: 20 AI art per day
    RETURN QUERY
    SELECT
        cqu.ai_art_count,
        CASE WHEN v_is_premium THEN 20 ELSE 1 END AS ai_art_limit,
        cqu.voice_minutes_used,
        CASE WHEN v_is_premium THEN 60 ELSE 5 END AS voice_minutes_limit,
        v_is_premium
    FROM creative_quota_usage cqu
    WHERE cqu.user_id = v_user_id AND cqu.date = v_today;
END;
$$;


ALTER FUNCTION "public"."get_creative_quota"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_effective_age_filter"("member_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" STABLE
    AS $$
DECLARE
    member_record RECORD;
    calculated_age INTEGER;
BEGIN
    SELECT * INTO member_record FROM family_members WHERE id = member_id;

    IF member_record.birth_date IS NOT NULL THEN
        calculated_age := calculate_age(member_record.birth_date);
    ELSE
        calculated_age := 18; -- Default to adult if no birth date
    END IF;

    -- Use override if set and higher than calculated age
    IF member_record.age_filter_override IS NOT NULL AND
       member_record.age_filter_override > calculated_age THEN
        RETURN member_record.age_filter_override;
    END IF;

    RETURN calculated_age;
END;
$$;


ALTER FUNCTION "public"."get_effective_age_filter"("member_id" "uuid") OWNER TO "postgres";


