    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "valid_prompt_category" CHECK (("category" = ANY (ARRAY['gratitude'::"text", 'reflection'::"text", 'growth'::"text", 'emotions'::"text", 'relationships'::"text", 'self_compassion'::"text", 'goals'::"text", 'challenges'::"text", 'mindfulness'::"text", 'creativity'::"text"])))
);


