CREATE OR REPLACE FUNCTION "public"."get_live_sessions"() RETURNS TABLE("id" "uuid", "title" "text", "description" "text", "session_type" "text", "scheduled_start" timestamp with time zone, "scheduled_end" timestamp with time zone, "audio_url" "text", "participant_count" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    ls.id,
    ls.title,
    ls.description,
    ls.session_type,
    ls.scheduled_start,
    ls.scheduled_end,
    ls.audio_url,
    COALESCE(p.cnt, 0) AS participant_count
  FROM live_sessions ls
  LEFT JOIN (
    SELECT session_id, COUNT(*) AS cnt
    FROM live_session_participants
    WHERE left_at IS NULL
    GROUP BY session_id
  ) p ON p.session_id = ls.id
  WHERE ls.is_active = TRUE
    AND ls.scheduled_end > NOW()
  ORDER BY ls.scheduled_start ASC
  LIMIT 10;
END;
$$;


