CREATE OR REPLACE FUNCTION "public"."get_notification_training_data"("p_user_id" "uuid", "p_days" integer DEFAULT 30) RETURNS TABLE("notification_type" "text", "hour_of_day" integer, "day_of_week" integer, "is_weekend" boolean, "predicted_engagement" numeric, "actual_outcome" "text", "context_signals" "jsonb")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        nee.notification_type,
        EXTRACT(HOUR FROM nee.created_at)::int AS hour_of_day,
        EXTRACT(DOW FROM nee.created_at)::int AS day_of_week,
        EXTRACT(DOW FROM nee.created_at) IN (0, 6) AS is_weekend,
        nee.predicted_engagement,
        nee.actual_outcome,
        COALESCE(nee.context_snapshot, '{}'::jsonb) AS context_signals
    FROM notification_engagement_events nee
    WHERE nee.user_id = p_user_id
      AND nee.created_at >= NOW() - INTERVAL '1 day' * p_days
      AND nee.actual_outcome IN ('opened', 'completed', 'dismissed', 'ignored')
    ORDER BY nee.created_at DESC;
END;
$$;


ALTER FUNCTION "public"."get_notification_training_data"("p_user_id" "uuid", "p_days" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_notification_training_data"("p_user_id" "uuid", "p_days" integer) IS 'Get engagement events for ML model training';



CREATE OR REPLACE FUNCTION "public"."get_pattern_eligible_users"("p_min_days" integer DEFAULT 14) RETURNS TABLE("user_id" "uuid", "mood_count" integer, "first_mood_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    m.user_id,
    COUNT(*)::INT AS mood_count,
    MIN(m.created_at) AS first_mood_at
  FROM moods m
  JOIN user_settings us ON us.user_id = m.user_id
  WHERE us.proactive_enabled = TRUE
    AND 'pattern_insight' = ANY(us.proactive_types_enabled)
  GROUP BY m.user_id
  HAVING
    COUNT(*) >= p_min_days
    AND MIN(m.created_at) < NOW() - (p_min_days || ' days')::INTERVAL;
END;
$$;


