CREATE OR REPLACE FUNCTION "public"."get_ritual_current_step"("p_ritual_id" "uuid", "p_ritual_type" "text", "p_scheduled_for" timestamp with time zone, "p_duration_seconds" integer) RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_elapsed_seconds INT;
  v_step_duration INT;
  v_step_count INT;
  v_current_step INT;
  v_time_remaining INT;
BEGIN
  -- Calculate elapsed time
  v_elapsed_seconds := GREATEST(0, EXTRACT(EPOCH FROM (NOW() - p_scheduled_for))::INT);

  -- Determine step configuration based on ritual type
  CASE p_ritual_type
    WHEN 'gratitude' THEN v_step_duration := 60; v_step_count := 3;
    WHEN 'grounding' THEN v_step_duration := 45; v_step_count := 4;
    WHEN 'wins' THEN v_step_duration := 60; v_step_count := 3;
    WHEN 'breathing' THEN v_step_duration := 36; v_step_count := 5;
    ELSE v_step_duration := 60; v_step_count := 3;
  END CASE;

  -- Calculate current step (0-indexed, capped at last step)
  v_current_step := LEAST(v_elapsed_seconds / v_step_duration, v_step_count - 1);

  -- Calculate time remaining in current step
  v_time_remaining := v_step_duration - (v_elapsed_seconds % v_step_duration);

  -- If ritual has completed
  IF v_elapsed_seconds >= p_duration_seconds THEN
    RETURN json_build_object(
      'completed', true,
      'stepIndex', v_step_count - 1,
      'timeRemaining', 0
    );
  END IF;

  RETURN json_build_object(
    'completed', false,
    'stepIndex', v_current_step,
    'timeRemaining', v_time_remaining,
    'totalElapsed', v_elapsed_seconds
  );
END;
$$;


ALTER FUNCTION "public"."get_ritual_current_step"("p_ritual_id" "uuid", "p_ritual_type" "text", "p_scheduled_for" timestamp with time zone, "p_duration_seconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_session_for_listener"("p_session_id" "uuid") RETURNS TABLE("id" "uuid", "seeker_display_name" "text", "session_type" "text", "topic_tags" "text"[], "seeker_mood_before" integer, "seeker_notes" "text", "is_anonymous" boolean, "status" "text", "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_user_id UUID := auth.uid();
    v_is_listener BOOLEAN;
BEGIN
    -- Verify caller is the listener for this session
    SELECT EXISTS (
        SELECT 1 FROM support_sessions ss
        JOIN listeners l ON l.id = ss.listener_id
        WHERE ss.id = p_session_id
        AND l.user_id = v_user_id
    ) INTO v_is_listener;

    IF NOT v_is_listener THEN
        RAISE EXCEPTION 'Not authorized to view this session';
    END IF;

    RETURN QUERY
    SELECT
        ss.id,
        -- Only show display name if NOT anonymous
        CASE
            WHEN ss.is_anonymous THEN 'Anonymous User'
            ELSE COALESCE(p.display_name, 'User')
        END AS seeker_display_name,
        ss.session_type,
        ss.topic_tags,
        ss.seeker_mood_before,
        -- Redact notes if anonymous and contains personal info
        CASE
            WHEN ss.is_anonymous THEN '[Notes hidden for privacy]'
            ELSE ss.seeker_notes
        END AS seeker_notes,
        ss.is_anonymous,
        ss.status,
        ss.created_at
    FROM support_sessions ss
    LEFT JOIN profiles p ON p.id = ss.seeker_id
    WHERE ss.id = p_session_id;
END;
$$;


