CREATE OR REPLACE FUNCTION "public"."get_sleep_resume_position"("p_user_id" "uuid", "p_content_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_position INTEGER;
BEGIN
    SELECT last_position_seconds INTO v_position
    FROM sleep_sessions
    WHERE user_id = p_user_id
      AND content_id = p_content_id
      AND completed = false
      AND last_position_seconds > 30  -- Only resume if > 30 seconds in
    ORDER BY started_at DESC
    LIMIT 1;

    RETURN COALESCE(v_position, 0);
END;
$$;


