CREATE OR REPLACE FUNCTION "public"."get_voice_minutes_remaining"("p_user_id" "uuid") RETURNS double precision
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_is_premium BOOLEAN;
    v_minutes_used FLOAT;
    v_limit FLOAT;
BEGIN
    -- Check premium status
    SELECT EXISTS(
        SELECT 1 FROM subscriptions
        WHERE user_id = p_user_id
        AND status = 'active'
        AND expires_at > NOW()
    ) INTO v_is_premium;

    -- Premium users have unlimited (return large number)
    IF v_is_premium THEN
        RETURN 999999.0;
    END IF;

    -- Get current period usage (month start)
    SELECT COALESCE(minutes_used, 0) INTO v_minutes_used
    FROM voice_usage
    WHERE user_id = p_user_id
    AND period_start = DATE_TRUNC('month', NOW())::DATE;

    -- Free tier limit: 3 minutes per month
    v_limit := 3.0;

    RETURN GREATEST(0, v_limit - COALESCE(v_minutes_used, 0));
END;
$$;


ALTER FUNCTION "public"."get_voice_minutes_remaining"("p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_weekly_engagement_stats"("p_user_id" "uuid") RETURNS TABLE("delivered" integer, "opened" integer, "completed" integer, "dismissed" integer, "engagement_rate" numeric, "period_start" timestamp with time zone, "period_end" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_week_start TIMESTAMPTZ;
    v_week_end TIMESTAMPTZ;
BEGIN
    v_week_start := date_trunc('week', NOW());
    v_week_end := v_week_start + INTERVAL '7 days';

    RETURN QUERY
    SELECT
        COUNT(*)::int AS delivered,
        COUNT(*) FILTER (WHERE actual_outcome = 'opened')::int AS opened,
        COUNT(*) FILTER (WHERE actual_outcome = 'completed')::int AS completed,
        COUNT(*) FILTER (WHERE actual_outcome = 'dismissed')::int AS dismissed,
        CASE
            WHEN COUNT(*) FILTER (WHERE actual_outcome IN ('opened', 'completed')) > 0
            THEN COUNT(*) FILTER (WHERE actual_outcome IN ('opened', 'completed'))::decimal / COUNT(*)::decimal
            ELSE 0
        END AS engagement_rate,
        v_week_start,
        v_week_end
    FROM notification_engagement_events
    WHERE user_id = p_user_id
      AND created_at >= v_week_start
      AND created_at < v_week_end
      AND actual_outcome IN ('delivered', 'opened', 'completed', 'dismissed');
END;
$$;


ALTER FUNCTION "public"."get_weekly_engagement_stats"("p_user_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_weekly_engagement_stats"("p_user_id" "uuid") IS 'Get weekly engagement statistics for a user';



CREATE OR REPLACE FUNCTION "public"."get_weighted_quest_for_user"("p_user_id" "uuid", "p_exclude_category" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER COST 500
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_quest_id UUID;
BEGIN
  -- Get quest weighted by user preferences
  SELECT qt.id INTO v_quest_id
  FROM quest_templates qt
  LEFT JOIN user_quest_preferences uqp
    ON uqp.user_id = p_user_id AND uqp.quest_category = qt.category::text
  WHERE qt.is_active = TRUE
    AND (p_exclude_category IS NULL OR qt.category::text != p_exclude_category)
  ORDER BY
    -- Prefer categories with higher completion rates
    COALESCE(uqp.completion_count::float / NULLIF(uqp.completion_count + uqp.skip_count, 0), 0.5) DESC,
    -- Prefer categories with higher ratings
    COALESCE(uqp.total_rating_sum::float / NULLIF(uqp.rating_count, 0), 3) DESC,
    -- Add randomness
    RANDOM()
  LIMIT 1;

  RETURN v_quest_id;
END;
$$;


ALTER FUNCTION "public"."get_weighted_quest_for_user"("p_user_id" "uuid", "p_exclude_category" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."handle_crisis_risk_assessment"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
    -- If risk level is crisis, also create a crisis_event for audit trail
    IF NEW.risk_level = 'crisis' THEN
        INSERT INTO crisis_events (
            user_id,
            trigger_type,
            trigger_content,
            intervention_type,
            response_shown
        ) VALUES (
            NEW.user_id,
            'predictive_risk',
            'Risk assessment score: ' || NEW.risk_score || '. Top factors: ' || array_to_string(NEW.top_factors, ', '),
            'crisis_protocol',
            'Proactive crisis resources shown'
        );
    END IF;

    RETURN NEW;
END;
$$;


