CREATE OR REPLACE FUNCTION "public"."increment_ai_art_quota"() RETURNS TABLE("new_count" integer, "limit_reached" boolean, "ai_art_limit" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_user_id UUID := auth.uid();
    v_today DATE := CURRENT_DATE;
    v_is_premium BOOLEAN;
    v_limit INTEGER;
    v_new_count INTEGER;
BEGIN
    -- Check if user is premium
    SELECT EXISTS(
        SELECT 1 FROM subscriptions
        WHERE user_id = v_user_id
        AND status = 'active'
    ) INTO v_is_premium;

    -- Free tier: 1 AI art per day (stricter paywall)
    -- Premium: 20 AI art per day
    v_limit := CASE WHEN v_is_premium THEN 20 ELSE 1 END;

    -- Upsert and increment
    INSERT INTO creative_quota_usage (user_id, date, ai_art_count, voice_minutes_used)
    VALUES (v_user_id, v_today, 1, 0)
    ON CONFLICT (user_id, date)
    DO UPDATE SET ai_art_count = creative_quota_usage.ai_art_count + 1
    RETURNING creative_quota_usage.ai_art_count INTO v_new_count;

    RETURN QUERY
    SELECT
        v_new_count,
        v_new_count >= v_limit,
        v_limit;
END;
$$;


ALTER FUNCTION "public"."increment_ai_art_quota"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."increment_arc_day"("p_user_arc_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_arc_duration INT;
  v_current_day INT;
  v_user_id UUID;
BEGIN
  -- CRITICAL: Verify caller owns the arc enrollment
  SELECT ua.current_day, ua.snapshot_duration_days, ua.user_id
  INTO v_current_day, v_arc_duration, v_user_id
  FROM user_quest_arcs ua
  WHERE ua.id = p_user_arc_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'User arc enrollment not found';
  END IF;

  -- Authorization check: only owner or service role can increment
  IF v_user_id != auth.uid() AND auth.role() != 'service_role' THEN
    RAISE EXCEPTION 'Unauthorized: cannot increment arc day for another user';
  END IF;

  -- Increment day
  UPDATE user_quest_arcs
  SET current_day = current_day + 1,
      last_quest_completed_at = NOW(),
      -- Mark completed if final day
      status = CASE
        WHEN v_current_day + 1 >= v_arc_duration THEN 'completed'
        ELSE status
      END,
      completed_at = CASE
        WHEN v_current_day + 1 >= v_arc_duration THEN NOW()
        ELSE completed_at
      END
  WHERE id = p_user_arc_id;

  -- Audit log
  INSERT INTO quest_arc_audit_log (user_id, user_arc_id, action, metadata)
  VALUES (v_user_id, p_user_arc_id, 'increment_day', jsonb_build_object(
    'old_day', v_current_day,
    'new_day', v_current_day + 1,
    'caller_role', auth.role()
  ));
END;
$$;


ALTER FUNCTION "public"."increment_arc_day"("p_user_arc_id" "uuid") OWNER TO "postgres";


