CREATE OR REPLACE FUNCTION "public"."insert_email_log_with_rate_limit_check"("p_user_id" "uuid", "p_email_log_data" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_count INT;
  v_within_limit BOOLEAN;
  v_result JSONB;
BEGIN
  -- Start transaction with serializable isolation to prevent TOCTOU
  -- Count sent emails in past 7 days with row-level lock to prevent concurrent reads
  SELECT COUNT(*)
  INTO v_count
  FROM email_logs
  WHERE user_id = p_user_id
    AND status = 'sent'
    AND sent_at > NOW() - INTERVAL '7 days'
  FOR UPDATE SKIP LOCKED;  -- Lock to prevent concurrent rate limit checks

  v_within_limit := v_count < 10;

  -- Insert email log entry
  INSERT INTO email_logs (
    user_id,
    email_type,
    template_version,
    message_id,
    status,
    sent_at,
    created_at
  )
  SELECT
    (p_email_log_data->>'user_id')::UUID,
    p_email_log_data->>'email_type',
    p_email_log_data->>'template_version',
    p_email_log_data->>'message_id',
    p_email_log_data->>'status',
    (p_email_log_data->>'sent_at')::TIMESTAMPTZ,
    (p_email_log_data->>'created_at')::TIMESTAMPTZ;

  v_result := jsonb_build_object(
    'success', true,
    'withinLimit', v_within_limit
  );

  RETURN v_result;
EXCEPTION WHEN OTHERS THEN
  v_result := jsonb_build_object(
    'success', false,
    'withinLimit', false,
    'error', SQLERRM
  );
  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."insert_email_log_with_rate_limit_check"("p_user_id" "uuid", "p_email_log_data" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."insert_proactive_messages_batch"("p_messages" "jsonb") RETURNS TABLE("id" "uuid", "user_id" "uuid", "trigger_type" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
BEGIN
  -- Create temp table for batch processing
  CREATE TEMP TABLE message_batch AS
  SELECT
    (item->>'user_id')::UUID AS user_id,
    item->>'trigger_type' AS trigger_type,
    item->>'message_content' AS message_content,
    item->>'delivery_channel' AS delivery_channel,
    (item->>'scheduled_for')::TIMESTAMPTZ AS scheduled_for
  FROM jsonb_array_elements(p_messages) AS item;

  -- Insert messages
  RETURN QUERY
  INSERT INTO proactive_messages (user_id, trigger_type, message_content, delivery_channel, scheduled_for, created_at)
  SELECT
    user_id,
    trigger_type,
    message_content,
    delivery_channel,
    scheduled_for,
    NOW()
  FROM message_batch
  RETURNING proactive_messages.id, proactive_messages.user_id, proactive_messages.trigger_type;
END;
$$;


