CREATE OR REPLACE FUNCTION "public"."is_handle_available"("p_handle" "text", "p_exclude_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_count INT;
BEGIN
  -- Normalize handle to lowercase
  p_handle := LOWER(TRIM(p_handle));

  -- Validate handle format (letters, numbers, underscores, 3-30 chars)
  IF NOT (p_handle ~ '^[a-z0-9_]{3,30}$') THEN
    -- Invalid format returns false (not available)
    RETURN FALSE;
  END IF;

  -- Check if handle exists (excluding specified user if provided)
  IF p_exclude_user_id IS NOT NULL THEN
    SELECT COUNT(*) INTO v_count
    FROM profiles
    WHERE handle = p_handle AND id != p_exclude_user_id;
  ELSE
    SELECT COUNT(*) INTO v_count
    FROM profiles
    WHERE handle = p_handle;
  END IF;

  -- Return true if no matches (handle is available)
  RETURN v_count = 0;
END;
$_$;


ALTER FUNCTION "public"."is_handle_available"("p_handle" "text", "p_exclude_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."is_in_quiet_hours"("p_current_hour" integer, "p_quiet_start" "text", "p_quiet_end" "text") RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
DECLARE
  v_start_hour INT;
  v_end_hour INT;
BEGIN
  -- If quiet hours not set, not in quiet hours
  IF p_quiet_start IS NULL OR p_quiet_end IS NULL THEN
    RETURN false;
  END IF;

  -- Parse hour from HH:MM format
  v_start_hour := SPLIT_PART(p_quiet_start, ':', 1)::int;
  v_end_hour := SPLIT_PART(p_quiet_end, ':', 1)::int;

  -- Handle wrap-around (e.g., 22:00 to 08:00)
  IF v_start_hour > v_end_hour THEN
    -- Quiet hours span midnight
    RETURN p_current_hour >= v_start_hour OR p_current_hour < v_end_hour;
  ELSE
    -- Normal range
    RETURN p_current_hour >= v_start_hour AND p_current_hour < v_end_hour;
  END IF;
END;
$$;


ALTER FUNCTION "public"."is_in_quiet_hours"("p_current_hour" integer, "p_quiet_start" "text", "p_quiet_end" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."is_in_quiet_hours"("p_current_hour" integer, "p_quiet_start" "text", "p_quiet_end" "text") IS 'Check if hour is within quiet hours (handles midnight wrap-around)';



