CREATE OR REPLACE FUNCTION "public"."join_anonymous_room"("p_room_id" "uuid") RETURNS TABLE("participant_id" "uuid", "anonymous_name" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_user_id UUID := auth.uid();
    v_participant_id UUID;
    v_anonymous_name TEXT;
BEGIN
    IF v_user_id IS NULL THEN
        RAISE EXCEPTION 'Not authenticated';
    END IF;

    -- Check room is active
    IF NOT EXISTS (SELECT 1 FROM anonymous_rooms WHERE id = p_room_id AND is_active = true) THEN
        RAISE EXCEPTION 'Room not available';
    END IF;

    -- Check if already in room
    SELECT arp.id, arp.anonymous_name
    INTO v_participant_id, v_anonymous_name
    FROM anonymous_room_participants arp
    WHERE arp.room_id = p_room_id AND arp.user_id = v_user_id AND arp.left_at IS NULL;

    IF v_participant_id IS NOT NULL THEN
        RETURN QUERY SELECT v_participant_id, v_anonymous_name;
        RETURN;
    END IF;

    -- Generate anonymous identity and join
    v_anonymous_name := generate_anonymous_name();

    INSERT INTO anonymous_room_participants (
        room_id,
        user_id,
        anonymous_name
    )
    VALUES (
        p_room_id,
        v_user_id,
        v_anonymous_name
    )
    RETURNING id INTO v_participant_id;

    RETURN QUERY SELECT v_participant_id, v_anonymous_name;
END;
$$;


ALTER FUNCTION "public"."join_anonymous_room"("p_room_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."join_circle_by_invite_code"("p_invite_code" "text") RETURNS TABLE("circle_id" "uuid", "circle_name" "text", "member_count" integer, "success" boolean, "message" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id UUID;
  v_circle_id UUID;
  v_circle_name TEXT;
  v_max_members INT;
  v_current_members INT;
BEGIN
  -- Get the authenticated user
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN QUERY SELECT NULL::UUID, NULL::TEXT, 0, false, 'Not authenticated'::TEXT;
    RETURN;
  END IF;

  -- Normalize invite code (uppercase, trim whitespace)
  p_invite_code := UPPER(TRIM(p_invite_code));

  -- Find the circle by invite code
  SELECT c.id, c.name, c.max_members
  INTO v_circle_id, v_circle_name, v_max_members
  FROM circles c
  WHERE c.invite_code = p_invite_code;

  IF v_circle_id IS NULL THEN
    RETURN QUERY SELECT NULL::UUID, NULL::TEXT, 0, false, 'Invalid invite code'::TEXT;
    RETURN;
  END IF;

  -- Check if user is already a member
  IF EXISTS (
    SELECT 1 FROM circle_members cm
    WHERE cm.circle_id = v_circle_id AND cm.user_id = v_user_id
  ) THEN
    -- Already a member - return success with circle info
    SELECT COUNT(*) INTO v_current_members
    FROM circle_members cm WHERE cm.circle_id = v_circle_id;

    RETURN QUERY SELECT v_circle_id, v_circle_name, v_current_members::INT, true, 'Already a member'::TEXT;
    RETURN;
  END IF;

  -- Check member limit
  SELECT COUNT(*) INTO v_current_members
  FROM circle_members cm WHERE cm.circle_id = v_circle_id;

  IF v_current_members >= v_max_members THEN
    RETURN QUERY SELECT v_circle_id, v_circle_name, v_current_members::INT, false, 'Circle is full'::TEXT;
    RETURN;
  END IF;

  -- Add user as member
  INSERT INTO circle_members (circle_id, user_id, role, joined_at)
  VALUES (v_circle_id, v_user_id, 'member', NOW());

  -- Return success
  RETURN QUERY SELECT v_circle_id, v_circle_name, (v_current_members + 1)::INT, true, 'Joined successfully'::TEXT;
END;
$$;


ALTER FUNCTION "public"."join_circle_by_invite_code"("p_invite_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."log_coach_encounter"("p_user_id" "uuid", "p_distortion_code" "text", "p_conversation_id" "uuid", "p_original_message_preview" "text", "p_reframe_text" "text", "p_confidence" numeric, "p_encounter_type" "text" DEFAULT 'chat'::"text") RETURNS TABLE("encounter_id" "uuid", "success" boolean, "error_message" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_encounter_id UUID;
BEGIN
  -- Validate inputs
  IF p_user_id IS NULL OR p_distortion_code IS NULL THEN
    RETURN QUERY SELECT NULL::UUID, FALSE, 'Missing required fields';
    RETURN;
  END IF;

  -- Check if distortion code exists
  IF NOT EXISTS (
    SELECT 1 FROM cognitive_distortions WHERE code = p_distortion_code
  ) THEN
    RETURN QUERY SELECT NULL::UUID, FALSE, 'Invalid distortion code';
    RETURN;
  END IF;

  -- Insert encounter atomically
  BEGIN
    INSERT INTO distortion_encounters (
      user_id,
      distortion_code,
      conversation_id,
      original_message_preview,
      reframe_offered,
      reframe_text,
      confidence,
      encounter_type,
      occurred_at
    ) VALUES (
      p_user_id,
      p_distortion_code,
      p_conversation_id,
      p_original_message_preview,
      TRUE,
      p_reframe_text,
      p_confidence,
      p_encounter_type,
      NOW()
    )
    RETURNING id INTO v_encounter_id;

    -- Also record shown interaction
    INSERT INTO coach_interactions (
      user_id,
      encounter_id,
      distortion_code,
      action,
      confidence,
      occurred_at
    ) VALUES (
      p_user_id,
      v_encounter_id,
      p_distortion_code,
      'shown',
      p_confidence,
      NOW()
    );

    RETURN QUERY SELECT v_encounter_id, TRUE, NULL::TEXT;

  EXCEPTION WHEN OTHERS THEN
    RETURN QUERY SELECT NULL::UUID, FALSE, SQLERRM;
  END;
END;
$$;


ALTER FUNCTION "public"."log_coach_encounter"("p_user_id" "uuid", "p_distortion_code" "text", "p_conversation_id" "uuid", "p_original_message_preview" "text", "p_reframe_text" "text", "p_confidence" numeric, "p_encounter_type" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."log_coach_encounter"("p_user_id" "uuid", "p_distortion_code" "text", "p_conversation_id" "uuid", "p_original_message_preview" "text", "p_reframe_text" "text", "p_confidence" numeric, "p_encounter_type" "text") IS 'Atomically logs a cognitive bias coach encounter with error handling. Returns encounter_id and success status.';



