CREATE OR REPLACE FUNCTION "public"."log_notification_engagement"("p_notification_id" "uuid", "p_notification_type" "text", "p_actual_outcome" "text", "p_predicted_engagement" numeric DEFAULT NULL::numeric, "p_context_snapshot" "jsonb" DEFAULT NULL::"jsonb", "p_user_feedback_score" integer DEFAULT NULL::integer, "p_user_feedback_text" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_event_id UUID;
    v_user_id UUID;
BEGIN
    -- Get user_id from notification_id (lookup in predictions or history)
    SELECT user_id INTO v_user_id
    FROM notification_predictions
    WHERE id = p_notification_id
    LIMIT 1;

    -- If not found in predictions, try notification_history
    IF v_user_id IS NULL THEN
        SELECT user_id INTO v_user_id
        FROM notification_history
        WHERE id = p_notification_id
        LIMIT 1;
    END IF;

    -- Insert engagement event
    INSERT INTO notification_engagement_events (
        notification_id,
        user_id,
        prediction_id,
        notification_type,
        predicted_engagement,
        context_snapshot,
        actual_outcome,
        user_feedback_score,
        user_feedback_text
    ) VALUES (
        p_notification_id,
        COALESCE(v_user_id, auth.uid()), -- Fallback to current user
        p_notification_id, -- Use notification_id as prediction_id if they match
        p_notification_type,
        p_predicted_engagement,
        p_context_snapshot,
        p_actual_outcome,
        p_user_feedback_score,
        p_user_feedback_text
    )
    RETURNING id INTO v_event_id;

    RETURN v_event_id;
END;
$$;


