CREATE OR REPLACE FUNCTION "public"."migrate_payloads_to_encrypted"() RETURNS TABLE("migrated_count" integer, "failed_count" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_migrated INT := 0;
  v_failed INT := 0;
BEGIN
  -- Note: Actual encryption would be done at application layer
  -- This function is a placeholder for manual encryption job
  -- Run via: SELECT migrate_payloads_to_encrypted();
  
  -- Mark rows that have plaintext payload but no encrypted_payload
IF EXISTS (
  SELECT 1 FROM information_schema.columns
  WHERE table_name = 'email_queue' AND column_name = 'payload'
) THEN
  UPDATE email_queue 
  SET encrypted_payload = payload::TEXT
  WHERE encrypted_payload IS NULL 
    AND payload IS NOT NULL
    AND payload != '{}'::jsonb;

  v_migrated := (SELECT COUNT(*) FROM email_queue WHERE encrypted_payload IS NOT NULL);
END IF;

  
  RETURN QUERY SELECT v_migrated, v_failed;
END;
$$;


ALTER FUNCTION "public"."migrate_payloads_to_encrypted"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."partner_sharing_exercises"() RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    partner_shares_exercises BOOLEAN;
    current_user_id UUID := auth.uid();
BEGIN
    SELECT 
        CASE 
            WHEN user_id_1 = current_user_id THEN user_2_share_exercises
            WHEN user_id_2 = current_user_id THEN user_1_share_exercises
        END
    INTO partner_shares_exercises
    FROM partner_links
    WHERE status = 'active'
    AND (user_id_1 = current_user_id OR user_id_2 = current_user_id);
    
    RETURN COALESCE(partner_shares_exercises, false);
END;
$$;


