CREATE OR REPLACE FUNCTION "public"."protect_therapist_sensitive_fields"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
    -- Only allow admins (service role) to modify these sensitive fields
    -- Regular users (authenticated via RLS) cannot change them

    -- Check if any sensitive field is being changed
    IF (OLD.verified IS DISTINCT FROM NEW.verified) OR
       (OLD.verified_at IS DISTINCT FROM NEW.verified_at) OR
       (OLD.background_check_passed IS DISTINCT FROM NEW.background_check_passed) OR
       (OLD.application_status IS DISTINCT FROM NEW.application_status) OR
       (OLD.rating_average IS DISTINCT FROM NEW.rating_average) OR
       (OLD.rating_count IS DISTINCT FROM NEW.rating_count) OR
       (OLD.sessions_completed IS DISTINCT FROM NEW.sessions_completed) THEN

        -- Check if this is being called via service role (admin)
        -- Service role bypasses RLS, so we check the current_setting
        IF current_setting('request.jwt.claims', true)::jsonb->>'role' = 'service_role' THEN
            -- Admin operation - allow all changes
            RETURN NEW;
        END IF;

        -- Regular user trying to modify sensitive fields - block the changes
        -- Reset sensitive fields to their original values
        NEW.verified := OLD.verified;
        NEW.verified_at := OLD.verified_at;
        NEW.background_check_passed := OLD.background_check_passed;
        NEW.application_status := OLD.application_status;
        NEW.rating_average := OLD.rating_average;
        NEW.rating_count := OLD.rating_count;
        NEW.sessions_completed := OLD.sessions_completed;
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."protect_therapist_sensitive_fields"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."protect_therapist_sensitive_fields"() IS 'Security trigger that prevents regular users from modifying sensitive fields like verified, application_status, ratings, etc. Only service_role (admin) can modify these.';



CREATE OR REPLACE FUNCTION "public"."record_proactive_engagement"("p_message_id" "uuid", "p_action" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id UUID;
BEGIN
  -- Get user_id from message
  SELECT user_id INTO v_user_id FROM proactive_messages WHERE id = p_message_id;

  IF v_user_id IS NULL THEN
    RETURN;
  END IF;

  -- Update message status
  UPDATE proactive_messages
  SET
    status = p_action,
    opened_at = CASE WHEN p_action IN ('opened', 'engaged') AND opened_at IS NULL THEN NOW() ELSE opened_at END,
    engaged_at = CASE WHEN p_action = 'engaged' THEN NOW() ELSE engaged_at END,
    dismissed_at = CASE WHEN p_action = 'dismissed' THEN NOW() ELSE dismissed_at END
  WHERE id = p_message_id;

  -- Update engagement state
  IF p_action = 'engaged' THEN
    -- Reset ignore count on engagement
    UPDATE user_engagement_states
    SET
      proactive_ignore_count = 0,
      last_activity_at = NOW(),
      updated_at = NOW()
    WHERE user_id = v_user_id;
  ELSIF p_action = 'dismissed' THEN
    -- Increment ignore count
    UPDATE user_engagement_states
    SET
      proactive_ignore_count = proactive_ignore_count + 1,
      updated_at = NOW()
    WHERE user_id = v_user_id;
  END IF;
END;
$$;


ALTER FUNCTION "public"."record_proactive_engagement"("p_message_id" "uuid", "p_action" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."record_proactive_engagement"("p_message_id" "uuid", "p_action" "text") IS 'Record user response to proactive message (opened/engaged/dismissed)';



CREATE OR REPLACE FUNCTION "public"."record_session_start"("p_user_id" "uuid") RETURNS TABLE("previous_absence_days" integer, "lapse_tier" "text", "is_returning" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_last_session TIMESTAMPTZ;
  v_days INT;
  v_tier TEXT;
BEGIN
  -- Get last session before updating
  SELECT last_session_at INTO v_last_session FROM profiles WHERE id = p_user_id;

  -- Calculate days absent
  v_days := COALESCE(EXTRACT(DAY FROM NOW() - v_last_session)::INT, 0);

  -- Determine tier
  v_tier := CASE
    WHEN v_days < 3 THEN 'active'
    WHEN v_days < 7 THEN 'brief_break'
    WHEN v_days < 14 THEN 'extended_break'
    WHEN v_days < 30 THEN 'long_absence'
    ELSE 'hiatus'
  END;

  -- Update the profile with new session timestamp
  UPDATE profiles SET
    last_session_at = NOW(),
    session_count = COALESCE(session_count, 0) + 1,
    last_absence_days = v_days
  WHERE id = p_user_id;

  -- Return info about the previous absence
  RETURN QUERY SELECT v_days, v_tier, (v_days >= 3);
END;
$$;


ALTER FUNCTION "public"."record_session_start"("p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."release_family_seat"("p_family_id" "uuid", "p_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_admin_sub RECORD;
    v_member RECORD;
BEGIN
    -- Lock the admin subscription row for update
    SELECT *
    INTO v_admin_sub
    FROM subscriptions
    WHERE family_id = p_family_id
      AND is_family_admin = true
    FOR UPDATE;

    IF v_admin_sub IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Family subscription not found',
            'code', 'NO_SUBSCRIPTION'
        );
    END IF;

    -- Find the member
    SELECT *
    INTO v_member
    FROM family_members
    WHERE family_id = p_family_id
      AND user_id = p_user_id
      AND status = 'active';

    IF v_member IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'User is not an active member of this family',
            'code', 'NOT_A_MEMBER'
        );
    END IF;

    -- Mark member as removed
    UPDATE family_members
    SET status = 'removed',
        removed_at = now()
    WHERE id = v_member.id;

    -- Decrement seats_used (but don't go below 1 - admin always counts)
    UPDATE subscriptions
    SET seats_used = GREATEST(1, seats_used - 1),
        updated_at = now()
    WHERE id = v_admin_sub.id;

    -- Log the event
    INSERT INTO billing_events (event_type, user_id, family_id, payload)
    VALUES (
        'family_seat_released',
        p_user_id,
        p_family_id,
        jsonb_build_object(
            'seats_used', GREATEST(1, v_admin_sub.seats_used - 1),
            'seats_total', v_admin_sub.seats_total
        )
    );

    RETURN jsonb_build_object(
        'success', true,
        'message', 'Seat released successfully',
        'seats_used', GREATEST(1, v_admin_sub.seats_used - 1),
        'seats_total', v_admin_sub.seats_total
    );
END;
$$;


ALTER FUNCTION "public"."release_family_seat"("p_family_id" "uuid", "p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."request_mentorship"("p_mentor_id" "uuid", "p_challenges" "text"[]) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_user_id UUID := auth.uid();
    v_mentorship_id UUID;
    v_mentor_days INTEGER;
BEGIN
    IF v_user_id IS NULL THEN
        RAISE EXCEPTION 'Not authenticated';
    END IF;

    IF v_user_id = p_mentor_id THEN
        RAISE EXCEPTION 'Cannot mentor yourself';
    END IF;

    -- Check mentor has 90+ days
    SELECT EXTRACT(EPOCH FROM (NOW() - created_at)) / 86400
    INTO v_mentor_days
    FROM profiles
    WHERE id = p_mentor_id;

    IF v_mentor_days < 90 THEN
        RAISE EXCEPTION 'Mentor must have 90+ days on platform';
    END IF;

    -- Check for existing mentorship
    IF EXISTS (
        SELECT 1 FROM mentorships
        WHERE mentor_id = p_mentor_id AND mentee_id = v_user_id
        AND status IN ('pending', 'active')
    ) THEN
        RAISE EXCEPTION 'Mentorship already exists';
    END IF;

    -- Create mentorship request
    INSERT INTO mentorships (
        mentor_id,
        mentee_id,
        matched_on_challenges,
        ends_at
    )
    VALUES (
        p_mentor_id,
        v_user_id,
        p_challenges,
        NOW() + INTERVAL '3 months'
    )
    RETURNING id INTO v_mentorship_id;

    RETURN v_mentorship_id;
END;
$$;


ALTER FUNCTION "public"."request_mentorship"("p_mentor_id" "uuid", "p_challenges" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reroll_quest"("p_user_id" "uuid", "p_alternatives_id" "uuid") RETURNS SETOF "public"."quest_alternatives"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_current quest_alternatives;
  v_new_quest_id UUID;
  v_current_category TEXT;
  v_new_quick UUID;
  v_result quest_alternatives;
BEGIN
  -- Get current alternatives
  SELECT * INTO v_current FROM quest_alternatives
  WHERE id = p_alternatives_id AND user_id = p_user_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Quest alternatives not found';
  END IF;

  -- Check if rerolls remaining
  IF v_current.rerolls_used >= v_current.rerolls_max AND v_current.rerolls_max != 999 THEN
    RAISE EXCEPTION 'No rerolls remaining';
  END IF;

  -- Get current quest category to exclude
  SELECT category::text INTO v_current_category FROM quest_templates WHERE id = v_current.primary_quest_id;

  -- Get new quest (different from current)
  SELECT id INTO v_new_quest_id
  FROM quest_templates
  WHERE is_active = TRUE
    AND category::text != COALESCE(v_current_category, '')
    AND id != v_current.primary_quest_id
  ORDER BY RANDOM()
  LIMIT 1;

  IF v_new_quest_id IS NULL THEN
    -- Fallback: just get any different quest
    SELECT id INTO v_new_quest_id
    FROM quest_templates
    WHERE is_active = TRUE AND id != v_current.primary_quest_id
    ORDER BY RANDOM()
    LIMIT 1;
  END IF;

  IF v_new_quest_id IS NULL THEN
    RAISE EXCEPTION 'No quest templates available';
  END IF;

  -- Get quick variant for new quest (if exists)
  SELECT id INTO v_new_quick FROM quest_quick_variants
  WHERE parent_template_id = v_new_quest_id;

  -- Log reroll history
  INSERT INTO quest_reroll_history (
    user_id, quest_date, from_quest_id, to_quest_id, reroll_number
  ) VALUES (
    p_user_id, v_current.quest_date, v_current.primary_quest_id, v_new_quest_id, v_current.rerolls_used + 1
  );

  -- Update alternatives
  UPDATE quest_alternatives
  SET
    primary_quest_id = v_new_quest_id,
    quick_variant_id = v_new_quick,
    rerolls_used = rerolls_used + 1,
    selected_variant = 'reroll'
  WHERE id = p_alternatives_id
  RETURNING * INTO v_result;

  RETURN NEXT v_result;
  RETURN;
END;
$$;


ALTER FUNCTION "public"."reroll_quest"("p_user_id" "uuid", "p_alternatives_id" "uuid") OWNER TO "postgres";


