CREATE OR REPLACE FUNCTION "public"."reset_weekly_shields"() RETURNS TABLE("users_reset" integer, "shield_events_created" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_users_reset INT;
  v_events_created INT;
BEGIN
  -- Batch insert audit events for users who had shields used (before reset)
  INSERT INTO streak_shield_events (user_id, event_type, shields_remaining, metadata)
  SELECT
    us.user_id,
    'reset',
    us.streak_shields_max,
    jsonb_build_object('previous_shields', us.streak_shields_remaining)
  FROM user_stats us
  WHERE us.streak_shields_remaining < us.streak_shields_max;

  GET DIAGNOSTICS v_events_created = ROW_COUNT;

  -- Batch update all eligible users in a single statement
  UPDATE user_stats SET
    streak_shields_remaining = streak_shields_max,
    shields_reset_at = NOW(),
    updated_at = NOW()
  WHERE streak_shields_remaining < streak_shields_max
     OR shields_reset_at IS NULL
     OR shields_reset_at < NOW() - INTERVAL '6 days';

  GET DIAGNOSTICS v_users_reset = ROW_COUNT;

  users_reset := v_users_reset;
  shield_events_created := v_events_created;
  RETURN NEXT;
END;
$$;


ALTER FUNCTION "public"."reset_weekly_shields"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reset_weekly_xp_if_needed"("p_user_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_current_week TEXT;
  v_last_reset_week TEXT;
  v_was_reset BOOLEAN := FALSE;
BEGIN
  -- Get ISO week string (YYYY-WW format)
  v_current_week := TO_CHAR(NOW(), 'IYYY-IW');

  -- Get user's last reset week
  SELECT last_xp_reset_week INTO v_last_reset_week
  FROM user_stats
  WHERE user_id = p_user_id;

  -- Reset if week changed
  IF v_last_reset_week IS NULL OR v_last_reset_week != v_current_week THEN
    UPDATE user_stats
    SET xp_this_week = 0,
        last_xp_reset_week = v_current_week,
        updated_at = NOW()
    WHERE user_id = p_user_id;
    v_was_reset := TRUE;
  END IF;

  RETURN v_was_reset;
END;
$$;


ALTER FUNCTION "public"."reset_weekly_xp_if_needed"("p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resume_program_enrollment"("p_enrollment_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id UUID := auth.uid();
  v_has_other_active BOOLEAN;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  -- Check if user has another active enrollment
  SELECT EXISTS(
    SELECT 1 FROM program_enrollments
    WHERE user_id = v_user_id
      AND status = 'active'
      AND id != p_enrollment_id
  ) INTO v_has_other_active;

  IF v_has_other_active THEN
    RAISE EXCEPTION 'Cannot resume: another program is already active';
  END IF;

  UPDATE program_enrollments SET
    status = 'active',
    paused_at = NULL,
    streak_days = 0,  -- Reset streak after pause
    updated_at = NOW()
  WHERE id = p_enrollment_id
    AND user_id = v_user_id
    AND status = 'paused';

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Enrollment not found, not owned by user, or not paused';
  END IF;
END;
$$;


ALTER FUNCTION "public"."resume_program_enrollment"("p_enrollment_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."revoke_family_premium_on_expiry"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_member RECORD;
BEGIN
    -- Only act when an admin subscription becomes inactive/expired
    IF NEW.is_family_admin = true
       AND OLD.status = 'active'
       AND NEW.status IN ('expired', 'cancelled', 'inactive') THEN

        -- Use advisory lock to prevent concurrent modifications
        PERFORM pg_advisory_xact_lock(hashtext('family_revoke_' || NEW.family_id::text));

        -- Revoke premium for all non-admin family members
        FOR v_member IN
            SELECT fm.user_id, fm.id as member_id
            FROM family_members fm
            WHERE fm.family_id = NEW.family_id
              AND fm.user_id != NEW.user_id
              AND fm.status = 'active'
        LOOP
            -- Update member's subscription status
            UPDATE subscriptions
            SET status = 'expired',
                expires_at = now(),
                updated_at = now()
            WHERE user_id = v_member.user_id
              AND family_id = NEW.family_id
              AND is_family_admin = false;

            -- Downgrade member's profile
            UPDATE profiles
            SET subscription_tier = 'free',
                daily_ai_quota = 20
            WHERE id = v_member.user_id;

            -- Log the event
            INSERT INTO billing_events (event_type, user_id, family_id, subscription_id, payload)
            VALUES (
                'subscription_expired',
                v_member.user_id,
                NEW.family_id,
                NEW.id,
                jsonb_build_object(
                    'reason', 'admin_subscription_expired',
                    'admin_user_id', NEW.user_id
                )
            );
        END LOOP;
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."revoke_family_premium_on_expiry"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_program_day_progress"("p_enrollment_id" "uuid", "p_day_number" integer, "p_content_completed" "jsonb", "p_reflection_response" "text" DEFAULT NULL::"text", "p_apply_report" "text" DEFAULT NULL::"text", "p_exercise_session_id" "uuid" DEFAULT NULL::"uuid", "p_mood_before" integer DEFAULT NULL::integer, "p_mood_after" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id UUID := auth.uid();
  v_enrollment_id UUID;
BEGIN
  -- Ensure user is authenticated
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  -- Verify enrollment ownership and get id
  SELECT id INTO v_enrollment_id FROM program_enrollments
  WHERE id = p_enrollment_id AND user_id = v_user_id;

  IF v_enrollment_id IS NULL THEN
    RAISE EXCEPTION 'Enrollment not found or access denied';
  END IF;

  -- Upsert progress
  -- Note: We only set status to 'in_progress' if it's currently 'pending'.
  -- If it's already 'completed' or 'skipped', we don't change the status back to 'in_progress'
  -- but we might still want to update the content (e.g. reflection).

  INSERT INTO program_day_progress (
    enrollment_id, day_number, status, started_at,
    content_completed, reflection_response, apply_report,
    exercise_session_id, mood_before, mood_after, updated_at
  ) VALUES (
    p_enrollment_id, p_day_number, 'in_progress', NOW(),
    p_content_completed, p_reflection_response, p_apply_report,
    p_exercise_session_id, p_mood_before, p_mood_after, NOW()
  )
  ON CONFLICT (enrollment_id, day_number)
  DO UPDATE SET
    status = CASE 
      WHEN program_day_progress.status = 'pending' THEN 'in_progress'
      ELSE program_day_progress.status
    END,
    content_completed = p_content_completed,
    reflection_response = COALESCE(p_reflection_response, program_day_progress.reflection_response),
    apply_report = COALESCE(p_apply_report, program_day_progress.apply_report),
    exercise_session_id = COALESCE(p_exercise_session_id, program_day_progress.exercise_session_id),
    mood_before = COALESCE(p_mood_before, program_day_progress.mood_before),
    mood_after = COALESCE(p_mood_after, program_day_progress.mood_after),
    updated_at = NOW();

  RETURN jsonb_build_object(
    'success', true,
    'day_number', p_day_number
  );
END;
$$;


ALTER FUNCTION "public"."save_program_day_progress"("p_enrollment_id" "uuid", "p_day_number" integer, "p_content_completed" "jsonb", "p_reflection_response" "text", "p_apply_report" "text", "p_exercise_session_id" "uuid", "p_mood_before" integer, "p_mood_after" integer) OWNER TO "postgres";


