CREATE OR REPLACE FUNCTION "public"."share_celebration_to_circles"("p_celebration_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id UUID;
  v_celebration RECORD;
  v_circle_id UUID;
  v_post_id UUID;
  v_post_content TEXT;
  v_user_name TEXT;
BEGIN
  -- Get the user ID from the celebration
  SELECT user_id, celebration_type, value, badge_id INTO v_celebration
  FROM celebration_events
  WHERE id = p_celebration_id AND user_id = auth.uid();

  IF v_celebration.user_id IS NULL THEN
    RAISE EXCEPTION 'Celebration not found or not owned by user';
  END IF;

  v_user_id := v_celebration.user_id;

  -- Get user display name
  SELECT display_name INTO v_user_name
  FROM profiles
  WHERE id = v_user_id;

  -- Generate post content based on celebration type
  CASE v_celebration.celebration_type
    WHEN 'streak_milestone' THEN
      v_post_content := '🔥 ' || COALESCE(v_user_name, 'A friend') || ' just hit a ' || v_celebration.value || '-day streak!';
    WHEN 'level_up' THEN
      v_post_content := '⭐ ' || COALESCE(v_user_name, 'A friend') || ' reached Level ' || v_celebration.value || '!';
    WHEN 'badge_unlock' THEN
      SELECT '🏆 ' || COALESCE(v_user_name, 'A friend') || ' earned the "' || title || '" badge!' INTO v_post_content
      FROM badges WHERE id = v_celebration.badge_id;
    WHEN 'quest_milestone' THEN
      v_post_content := '💪 ' || COALESCE(v_user_name, 'A friend') || ' completed ' || v_celebration.value || ' quests!';
    WHEN 'exercise_milestone' THEN
      v_post_content := '🧘 ' || COALESCE(v_user_name, 'A friend') || ' completed ' || v_celebration.value || ' exercises!';
    ELSE
      v_post_content := '🎉 ' || COALESCE(v_user_name, 'A friend') || ' achieved a milestone!';
  END CASE;

  -- Get user's primary circle (first circle they're a member of)
  SELECT cm.circle_id INTO v_circle_id
  FROM circle_members cm
  WHERE cm.user_id = v_user_id
  ORDER BY cm.joined_at
  LIMIT 1;

  IF v_circle_id IS NOT NULL THEN
    -- Create the circle post
    INSERT INTO circle_posts (circle_id, user_id, post_type, mood_emoji, body_text, local_date)
    VALUES (
      v_circle_id,
      v_user_id,
      'milestone',
      '🎉',
      v_post_content,
      TO_CHAR(NOW() AT TIME ZONE 'UTC', 'YYYY-MM-DD')
    )
    RETURNING id INTO v_post_id;

    -- Update the celebration to mark as shared
    UPDATE celebration_events
    SET shared_to_circle = TRUE,
        circle_post_id = v_post_id
    WHERE id = p_celebration_id;
  END IF;

  RETURN v_post_id;
END;
$$;


ALTER FUNCTION "public"."share_celebration_to_circles"("p_celebration_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."skip_program_day"("p_enrollment_id" "uuid", "p_day_number" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id UUID := auth.uid();
  v_enrollment program_enrollments%ROWTYPE;
  v_program programs%ROWTYPE;
BEGIN
  -- Ensure user is authenticated
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  -- Get enrollment and verify ownership
  SELECT * INTO v_enrollment FROM program_enrollments
  WHERE id = p_enrollment_id AND user_id = v_user_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Enrollment not found or access denied';
  END IF;

  IF v_enrollment.status != 'active' THEN
    RAISE EXCEPTION 'Enrollment is not active';
  END IF;

  IF v_enrollment.skips_used >= v_enrollment.skips_allowed THEN
    RAISE EXCEPTION 'No skips remaining';
  END IF;

  -- Get program
  SELECT * INTO v_program FROM programs WHERE id = v_enrollment.program_id;

  -- Mark day as skipped
  INSERT INTO program_day_progress (
    enrollment_id, day_number, status, completed_at
  ) VALUES (
    p_enrollment_id, p_day_number, 'skipped', NOW()
  )
  ON CONFLICT (enrollment_id, day_number)
  DO UPDATE SET
    status = 'skipped',
    completed_at = NOW(),
    updated_at = NOW();

  -- Update enrollment
  UPDATE program_enrollments SET
    skips_used = skips_used + 1,
    current_day = LEAST(current_day + 1, v_program.duration_days),
    streak_days = 0,  -- Reset streak on skip
    updated_at = NOW()
  WHERE id = p_enrollment_id
  RETURNING * INTO v_enrollment;

  -- Create next day progress entry
  INSERT INTO program_day_progress (enrollment_id, day_number, status)
  VALUES (p_enrollment_id, p_day_number + 1, 'pending')
  ON CONFLICT DO NOTHING;

  RETURN jsonb_build_object(
    'day_skipped', p_day_number,
    'skips_remaining', v_enrollment.skips_allowed - v_enrollment.skips_used,
    'next_day', p_day_number + 1
  );
END;
$$;


ALTER FUNCTION "public"."skip_program_day"("p_enrollment_id" "uuid", "p_day_number" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."start_listener_training"() RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_user_id UUID := auth.uid();
    v_listener_id UUID;
BEGIN
    IF v_user_id IS NULL THEN
        RAISE EXCEPTION 'Not authenticated';
    END IF;

    SELECT id INTO v_listener_id
    FROM listeners
    WHERE user_id = v_user_id AND status = 'applicant';

    IF v_listener_id IS NULL THEN
        RAISE EXCEPTION 'Not an applicant';
    END IF;

    UPDATE listeners
    SET
        status = 'training',
        training_started_at = NOW(),
        updated_at = NOW()
    WHERE id = v_listener_id;

    RETURN TRUE;
END;
$$;


