CREATE OR REPLACE FUNCTION "public"."start_recovery_quest"("p_user_id" "uuid") RETURNS TABLE("success" boolean, "attempt_id" "uuid", "quest_template_id" "uuid", "quest_title" "text", "quest_description" "text", "quest_estimated_minutes" integer, "quest_instructions" "jsonb", "error_message" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_stats RECORD;
  v_template RECORD;
  v_attempt_id UUID;
  v_attempt_number INT;
  v_template_count INT;
BEGIN
  -- Security check
  IF auth.uid() IS NOT NULL AND auth.uid() != p_user_id THEN
    RAISE EXCEPTION 'Unauthorized: cannot start recovery for another user';
  END IF;

  -- Get user stats with row lock to prevent TOCTOU race conditions
  SELECT * INTO v_stats
  FROM user_stats
  WHERE user_id = p_user_id
  FOR UPDATE NOWAIT;

  IF v_stats IS NULL THEN
    RETURN QUERY SELECT FALSE, NULL::UUID, NULL::UUID, NULL::TEXT, NULL::TEXT, NULL::INT, NULL::JSONB, 'User stats not found'::TEXT;
    RETURN;
  END IF;

  -- Check if recovery is available
  IF NOT v_stats.recovery_quest_available THEN
    RETURN QUERY SELECT FALSE, NULL::UUID, NULL::UUID, NULL::TEXT, NULL::TEXT, NULL::INT, NULL::JSONB, 'Recovery quest not available'::TEXT;
    RETURN;
  END IF;

  -- Check if recovery window expired (with NULL handling)
  IF v_stats.recovery_quest_expires_at IS NULL OR v_stats.recovery_quest_expires_at < NOW() THEN
    RETURN QUERY SELECT FALSE, NULL::UUID, NULL::UUID, NULL::TEXT, NULL::TEXT, NULL::INT, NULL::JSONB, 'Recovery window expired'::TEXT;
    RETURN;
  END IF;

  -- Check remaining attempts
  IF v_stats.recovery_attempts_remaining <= 0 THEN
    RETURN QUERY SELECT FALSE, NULL::UUID, NULL::UUID, NULL::TEXT, NULL::TEXT, NULL::INT, NULL::JSONB, 'No recovery attempts remaining'::TEXT;
    RETURN;
  END IF;

  -- Check for existing in-progress recovery (with lock to prevent race)
  IF EXISTS (
    SELECT 1 FROM recovery_quest_attempts
    WHERE user_id = p_user_id AND status = 'in_progress'
    FOR UPDATE SKIP LOCKED
  ) THEN
    RETURN QUERY SELECT FALSE, NULL::UUID, NULL::UUID, NULL::TEXT, NULL::TEXT, NULL::INT, NULL::JSONB, 'Recovery quest already in progress'::TEXT;
    RETURN;
  END IF;

  -- Get a longer quest template (10+ minutes) using efficient random selection
  -- Using OFFSET with random() is more efficient than ORDER BY RANDOM()
  SELECT COUNT(*) INTO v_template_count
  FROM quest_templates
  WHERE estimated_minutes >= 10
    AND (is_active IS NULL OR is_active = TRUE);

  IF v_template_count > 0 THEN
    SELECT * INTO v_template
    FROM quest_templates
    WHERE estimated_minutes >= 10
      AND (is_active IS NULL OR is_active = TRUE)
    OFFSET floor(random() * v_template_count)
    LIMIT 1;
  END IF;

  IF v_template IS NULL THEN
    -- Fallback to any template
    SELECT COUNT(*) INTO v_template_count FROM quest_templates;
    IF v_template_count > 0 THEN
      SELECT * INTO v_template
      FROM quest_templates
      OFFSET floor(random() * v_template_count)
      LIMIT 1;
    END IF;
  END IF;

  IF v_template IS NULL THEN
    RETURN QUERY SELECT FALSE, NULL::UUID, NULL::UUID, NULL::TEXT, NULL::TEXT, NULL::INT, NULL::JSONB, 'No quest templates available'::TEXT;
    RETURN;
  END IF;

  -- Calculate attempt number
  v_attempt_number := v_stats.recovery_attempts_max - v_stats.recovery_attempts_remaining + 1;

  -- Create recovery attempt
  INSERT INTO recovery_quest_attempts (
    user_id,
    streak_to_recover,
    quest_template_id,
    attempt_number,
    status,
    expired_at
  )
  VALUES (
    p_user_id,
    v_stats.streak_before_break,
    v_template.id,
    v_attempt_number,
    'in_progress',
    v_stats.recovery_quest_expires_at
  )
  RETURNING id INTO v_attempt_id;

  -- Decrement remaining attempts
  UPDATE user_stats SET
    recovery_attempts_remaining = recovery_attempts_remaining - 1,
    updated_at = NOW()
  WHERE user_id = p_user_id;

  RETURN QUERY SELECT
    TRUE,
    v_attempt_id,
    v_template.id,
    v_template.title,
    v_template.description,
    v_template.estimated_minutes,
    v_template.instructions,
    NULL::TEXT;
END;
$$;


ALTER FUNCTION "public"."start_recovery_quest"("p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_clinical_assessment"("p_assessment_type" "text", "p_responses" integer[], "p_enrollment_id" "uuid" DEFAULT NULL::"uuid", "p_assessment_point" "text" DEFAULT 'standalone'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_user_id UUID;
    v_total_score INT;
    v_severity TEXT;
    v_flagged BOOLEAN;
    v_phq9_q9_score INT;
    v_assessment_id UUID;
    v_crisis_intervention_needed BOOLEAN := FALSE;
BEGIN
    v_user_id := auth.uid();

    IF v_user_id IS NULL THEN
        RETURN jsonb_build_object(
            'error', 'NOT_AUTHENTICATED',
            'message', 'User must be authenticated'
        );
    END IF;

    -- Validate assessment type
    IF p_assessment_type NOT IN ('phq9', 'gad7', 'weekly_checkin') THEN
        RETURN jsonb_build_object(
            'error', 'INVALID_ASSESSMENT_TYPE',
            'message', 'Assessment type must be phq9, gad7, or weekly_checkin'
        );
    END IF;

    -- Validate response count
    IF p_assessment_type = 'phq9' AND array_length(p_responses, 1) != 9 THEN
        RETURN jsonb_build_object(
            'error', 'INVALID_RESPONSE_COUNT',
            'message', 'PHQ-9 requires exactly 9 responses'
        );
    END IF;

    IF p_assessment_type = 'gad7' AND array_length(p_responses, 1) != 7 THEN
        RETURN jsonb_build_object(
            'error', 'INVALID_RESPONSE_COUNT',
            'message', 'GAD-7 requires exactly 7 responses'
        );
    END IF;

    -- Calculate total score
    SELECT COALESCE(SUM(val), 0) INTO v_total_score
    FROM unnest(p_responses) AS val;

    -- Calculate severity
    v_severity := calculate_assessment_severity(p_assessment_type, v_total_score);

    -- Check for safety flagging
    -- Flag if: PHQ-9 Q9 >= 1 (suicidal ideation) OR total score >= 15 (moderately severe+)
    v_flagged := FALSE;

    IF p_assessment_type = 'phq9' THEN
        v_phq9_q9_score := p_responses[9];  -- Q9 is the last question (1-indexed in SQL)

        IF v_phq9_q9_score >= 1 THEN
            v_flagged := TRUE;
            v_crisis_intervention_needed := TRUE;

            -- Log crisis event for Q9 positive (suicidal ideation)
            INSERT INTO crisis_events (user_id, trigger_keyword, detected_at, source, severity)
            VALUES (v_user_id, 'PHQ9_Q9_POSITIVE', NOW(), 'assessment',
                CASE
                    WHEN v_phq9_q9_score = 3 THEN 'critical'
                    WHEN v_phq9_q9_score = 2 THEN 'high'
                    ELSE 'moderate'
                END
            );
        END IF;
    END IF;

    -- Also flag if total score indicates moderately severe or worse
    IF v_total_score >= 15 THEN
        v_flagged := TRUE;
    END IF;

    -- Insert the assessment
    INSERT INTO clinical_assessments (
        user_id, enrollment_id, assessment_type, responses,
        total_score, severity, flagged_for_review, assessment_point
    )
    VALUES (
        v_user_id, p_enrollment_id, p_assessment_type, to_jsonb(p_responses),
        v_total_score, v_severity, v_flagged, p_assessment_point
    )
    RETURNING id INTO v_assessment_id;

    -- If this is a baseline assessment, link it to the enrollment
    IF p_enrollment_id IS NOT NULL AND p_assessment_point = 'pre' THEN
        UPDATE program_enrollments
        SET baseline_assessment_id = v_assessment_id,
            baseline_assessment_completed_at = NOW()
        WHERE id = p_enrollment_id AND user_id = v_user_id;
    END IF;

    RETURN jsonb_build_object(
        'id', v_assessment_id,
        'assessment_type', p_assessment_type,
        'total_score', v_total_score,
        'severity', v_severity,
        'flagged_for_review', v_flagged,
        'crisis_intervention_needed', v_crisis_intervention_needed,
        'interpretation', CASE v_severity
            WHEN 'minimal' THEN 'Your score suggests minimal symptoms.'
            WHEN 'mild' THEN 'Your score suggests mild symptoms.'
            WHEN 'moderate' THEN 'Your score suggests moderate symptoms. Consider speaking with a mental health professional.'
            WHEN 'moderately_severe' THEN 'Your score suggests moderately severe symptoms. We recommend speaking with a mental health professional.'
            WHEN 'severe' THEN 'Your score suggests severe symptoms. Please consider reaching out to a mental health professional as soon as possible.'
        END,
        'safety_action', CASE
            WHEN v_crisis_intervention_needed THEN jsonb_build_object(
                'type', 'CRISIS_MODAL',
                'mandatory_display_seconds', 5,
                'resources', jsonb_build_array(
                    jsonb_build_object('name', '988 Suicide & Crisis Lifeline', 'action', 'call', 'value', '988'),
                    jsonb_build_object('name', 'Crisis Text Line', 'action', 'sms', 'value', '741741', 'message', 'HOME')
                )
            )
            WHEN v_severity IN ('severe', 'moderately_severe') THEN jsonb_build_object(
                'type', 'SHOW_RECOMMENDATION',
                'message', 'We recommend speaking with a mental health professional alongside this program.'
            )
            ELSE NULL
        END
    );
END;
$$;


ALTER FUNCTION "public"."submit_clinical_assessment"("p_assessment_type" "text", "p_responses" integer[], "p_enrollment_id" "uuid", "p_assessment_point" "text") OWNER TO "postgres";


