CREATE OR REPLACE FUNCTION "public"."update_audio_track_rating"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    UPDATE audio_tracks SET
        average_rating = (
            SELECT AVG(rating)::NUMERIC(3,2)
            FROM audio_ratings
            WHERE track_id = COALESCE(NEW.track_id, OLD.track_id)
        ),
        rating_count = (
            SELECT COUNT(*)
            FROM audio_ratings
            WHERE track_id = COALESCE(NEW.track_id, OLD.track_id)
        ),
        updated_at = NOW()
    WHERE id = COALESCE(NEW.track_id, OLD.track_id);
    RETURN COALESCE(NEW, OLD);
END;
$$;


