COMMENT ON FUNCTION "public"."update_companion_memory_usage"("memory_ids" "uuid"[], "used_at" timestamp with time zone, "for_user_id" "uuid") IS 'Updates last_used_at and increments usage_count for companion memories (validates ownership)';



CREATE OR REPLACE FUNCTION "public"."update_content_rating_average"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    target_content_id UUID;
BEGIN
    IF TG_OP = 'DELETE' THEN
        target_content_id := OLD.content_id;
    ELSE
        target_content_id := NEW.content_id;
    END IF;

    UPDATE creator_content
    SET
        average_rating = (
            SELECT AVG(rating)::DECIMAL(3,2)
            FROM content_ratings
            WHERE content_id = target_content_id
        ),
        rating_count = (
            SELECT COUNT(*)
            FROM content_ratings
            WHERE content_id = target_content_id
        ),
        updated_at = NOW()
    WHERE id = target_content_id;

    IF TG_OP = 'DELETE' THEN
        RETURN OLD;
    ELSE
        RETURN NEW;
    END IF;
END;
$$;


