CREATE OR REPLACE FUNCTION "public"."update_journal_streak"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    user_tz TEXT;
    user_today DATE;
    last_date DATE;
    curr_streak INTEGER;
    long_streak INTEGER;
    total INTEGER;
BEGIN
    -- Get user's timezone (default to UTC)
    SELECT COALESCE(timezone, 'UTC') INTO user_tz
    FROM journal_streaks
    WHERE user_id = NEW.user_id;

    IF user_tz IS NULL THEN
        user_tz := 'UTC';
    END IF;

    -- Calculate today in user's timezone
    user_today := (NOW() AT TIME ZONE user_tz)::date;

    -- Get current streak data
    SELECT last_entry_date, current_streak, longest_streak, total_entries
    INTO last_date, curr_streak, long_streak, total
    FROM journal_streaks
    WHERE user_id = NEW.user_id;

    -- If no streak record exists, create one
    IF NOT FOUND THEN
        INSERT INTO journal_streaks (user_id, current_streak, longest_streak, last_entry_date, streak_started_at, total_entries, timezone)
        VALUES (NEW.user_id, 1, 1, user_today, user_today, 1, user_tz);
        RETURN NEW;
    END IF;

    -- If already journaled today, just increment total if this is a new entry
    IF last_date = user_today THEN
        UPDATE journal_streaks
        SET total_entries = total + 1,
            updated_at = NOW()
        WHERE user_id = NEW.user_id;
        RETURN NEW;
    END IF;

    -- Check if streak continues (journaled yesterday)
    IF last_date = user_today - 1 THEN
        curr_streak := curr_streak + 1;
    ELSE
        -- Streak broken, start new
        curr_streak := 1;
        UPDATE journal_streaks
        SET streak_started_at = user_today
        WHERE user_id = NEW.user_id;
    END IF;

    -- Update longest streak if needed
    IF curr_streak > long_streak THEN
        long_streak := curr_streak;
    END IF;

    -- Update streak record
    UPDATE journal_streaks
    SET current_streak = curr_streak,
        longest_streak = long_streak,
        last_entry_date = user_today,
        total_entries = total + 1,
        updated_at = NOW()
    WHERE user_id = NEW.user_id;

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."update_journal_streak"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."update_journal_streak"() IS 'Updates user streak when a new journal entry is created';



CREATE OR REPLACE FUNCTION "public"."update_listener_rating"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_listener_id UUID;
BEGIN
    -- Get the listener for this session
    SELECT listener_id INTO v_listener_id
    FROM support_sessions
    WHERE id = NEW.session_id;

    IF v_listener_id IS NOT NULL THEN
        -- Recalculate average rating
        UPDATE listeners
        SET
            average_rating = (
                SELECT AVG(sf.rating)::DECIMAL(3,2)
                FROM session_feedback sf
                JOIN support_sessions ss ON ss.id = sf.session_id
                WHERE ss.listener_id = v_listener_id
            ),
            rating_count = rating_count + 1,
            updated_at = NOW()
        WHERE id = v_listener_id;
    END IF;
    RETURN NEW;
END;
$$;


