    "user_2_rating" smallint,
    "user_1_notes" "text",
    "user_2_notes" "text",
    "user_1_progress_percent" smallint DEFAULT 0 NOT NULL,
    "user_2_progress_percent" smallint DEFAULT 0 NOT NULL,
    "started_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "completed_at" timestamp with time zone,
    "last_activity_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "couples_exercise_sessions_status_check" CHECK ((("status")::"text" = ANY ((ARRAY['pending'::character varying, 'in_progress'::character varying, 'paused'::character varying, 'completed'::character varying, 'abandoned'::character varying])::"text"[]))),
    CONSTRAINT "couples_exercise_sessions_user_1_notes_check" CHECK (("char_length"("user_1_notes") <= 500)),
    CONSTRAINT "couples_exercise_sessions_user_1_progress_percent_check" CHECK ((("user_1_progress_percent" >= 0) AND ("user_1_progress_percent" <= 100))),
    CONSTRAINT "couples_exercise_sessions_user_1_rating_check" CHECK ((("user_1_rating" >= 1) AND ("user_1_rating" <= 10))),
    CONSTRAINT "couples_exercise_sessions_user_2_notes_check" CHECK (("char_length"("user_2_notes") <= 500)),
    CONSTRAINT "couples_exercise_sessions_user_2_progress_percent_check" CHECK ((("user_2_progress_percent" >= 0) AND ("user_2_progress_percent" <= 100))),
    CONSTRAINT "couples_exercise_sessions_user_2_rating_check" CHECK ((("user_2_rating" >= 1) AND ("user_2_rating" <= 10))),
    CONSTRAINT "rating_requires_completion" CHECK ((((("status")::"text" <> 'completed'::"text") AND ("user_1_rating" IS NULL) AND ("user_2_rating" IS NULL)) OR ((("status")::"text" = 'completed'::"text") AND ("user_1_rating" IS NOT NULL) AND ("user_2_rating" IS NOT NULL)))),
    CONSTRAINT "valid_users" CHECK (("user_id_1" <> COALESCE("user_id_2", "user_id_1")))
);


ALTER TABLE "public"."couples_exercise_sessions" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_session_rating"("p_session_id" "uuid", "p_user_id" "uuid", "p_rating" integer, "p_notes" "text") RETURNS "public"."couples_exercise_sessions"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_session couples_exercise_sessions;
BEGIN
  -- Lock the row for update to prevent race conditions
  SELECT * INTO v_session FROM couples_exercise_sessions
    WHERE id = p_session_id
    FOR UPDATE;

  -- Validate session exists
  IF v_session IS NULL THEN
    RAISE EXCEPTION 'Session not found';
  END IF;

  -- Validate rating is within valid range (1-5)
  IF p_rating < 1 OR p_rating > 5 THEN
    RAISE EXCEPTION 'Rating must be between 1 and 5';
  END IF;

  -- Update rating for the appropriate user
  IF v_session.user_id_1 = p_user_id THEN
    UPDATE couples_exercise_sessions
      SET
        user_1_rating = p_rating,
        user_1_notes = p_notes,
        -- Mark session completed if both users have now rated
        status = CASE
          WHEN user_2_rating IS NOT NULL THEN 'completed'
          ELSE status
        END,
        completed_at = CASE
          WHEN user_2_rating IS NOT NULL THEN NOW()
          ELSE completed_at
        END,
        updated_at = NOW()
      WHERE id = p_session_id
      RETURNING * INTO v_session;
  ELSIF v_session.user_id_2 = p_user_id THEN
    UPDATE couples_exercise_sessions
      SET
        user_2_rating = p_rating,
        user_2_notes = p_notes,
        -- Mark session completed if both users have now rated
        status = CASE
          WHEN user_1_rating IS NOT NULL THEN 'completed'
          ELSE status
        END,
        completed_at = CASE
          WHEN user_1_rating IS NOT NULL THEN NOW()
          ELSE completed_at
        END,
        updated_at = NOW()
      WHERE id = p_session_id
      RETURNING * INTO v_session;
  ELSE
    RAISE EXCEPTION 'User is not part of this session';
  END IF;

  RETURN v_session;
END;
$$;


ALTER FUNCTION "public"."update_session_rating"("p_session_id" "uuid", "p_user_id" "uuid", "p_rating" integer, "p_notes" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."update_session_rating"("p_session_id" "uuid", "p_user_id" "uuid", "p_rating" integer, "p_notes" "text") IS 'Atomically update session rating for a user. Transitions session to completed when both users have rated.';



