CREATE OR REPLACE FUNCTION "public"."user_already_partnered"() RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    is_partnered BOOLEAN;
BEGIN
    SELECT EXISTS(
        SELECT 1 FROM partner_links
        WHERE status = 'active'
        AND (user_id_1 = auth.uid() OR user_id_2 = auth.uid())
        AND user_id_2 IS NOT NULL
    ) INTO is_partnered;
    
    RETURN COALESCE(is_partnered, false);
END;
$$;


