CREATE OR REPLACE FUNCTION "public"."user_has_premium"("user_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER COST 50
    SET "search_path" TO 'public'
    AS $_$
DECLARE
    has_active_premium BOOLEAN;
BEGIN
    SELECT EXISTS(
        SELECT 1 FROM subscriptions
        WHERE subscriptions.user_id = $1
        AND status = 'active'
        AND (cancel_at IS NULL OR cancel_at > now())
    ) INTO has_active_premium;
    
    RETURN COALESCE(has_active_premium, false);
END;
$_$;


ALTER FUNCTION "public"."user_has_premium"("user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."user_or_partner_has_premium"() RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    current_user_id UUID := auth.uid();
    partner_id UUID;
    current_has_premium BOOLEAN;
    partner_has_premium BOOLEAN;
BEGIN
    -- Check current user's premium status
    current_has_premium := user_has_premium(current_user_id);
    
    IF current_has_premium THEN
        RETURN true;
    END IF;
    
    -- Check partner's premium status if partnered
    partner_id := get_active_partner_id();
    IF partner_id IS NOT NULL THEN
        partner_has_premium := user_has_premium(partner_id);
        RETURN partner_has_premium;
    END IF;
    
    RETURN false;
END;
$$;


ALTER FUNCTION "public"."user_or_partner_has_premium"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."verify_invite_code"("code_hash" character varying) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
    link_id UUID;
BEGIN
    SELECT id
    INTO link_id
    FROM partner_links
    WHERE invite_code_hash = $1
    AND status = 'pending'
    AND expires_at > now()
    AND user_id_2 IS NULL
    LIMIT 1;
    
    RETURN link_id;
END;
$_$;


ALTER FUNCTION "public"."verify_invite_code"("code_hash" character varying) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."xp_for_level"("level" integer) RETURNS integer
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
BEGIN
    -- XP needed = 50 * (level^2 - (level-1)^2)
    RETURN 50 * (level * level - (level - 1) * (level - 1));
END;
$$;


ALTER FUNCTION "public"."xp_for_level"("level" integer) OWNER TO "postgres";


