COMMENT ON TABLE "public"."memory_fragments" IS 'AI-extracted facts from user conversations for personalization';



COMMENT ON COLUMN "public"."memory_fragments"."fragment_type" IS 'Type: person (names), event (upcoming/past), preference (likes/dislikes), fact (job/location/hobbies)';



COMMENT ON COLUMN "public"."memory_fragments"."key" IS 'Short identifier for the memory (e.g., dog_name, work_location)';



COMMENT ON COLUMN "public"."memory_fragments"."value" IS 'The actual content/value of the memory';



COMMENT ON COLUMN "public"."memory_fragments"."confidence" IS 'Extraction confidence score (0.0-1.0), higher = more certain';



COMMENT ON COLUMN "public"."memory_fragments"."expires_at" IS 'NULL for permanent types (person/preference/fact), set to event date + 7 days for events';



