CREATE TABLE IF NOT EXISTS "public"."user_badges_v2" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "user_id" "uuid" NOT NULL,
    "badge_id" "uuid" NOT NULL,
    "progress_current" integer DEFAULT 0,
    "progress_target" integer,
    "progress_percentage" numeric(5,2) GENERATED ALWAYS AS (
CASE
    WHEN (("progress_target" > 0) AND ("progress_target" IS NOT NULL)) THEN LEAST(((("progress_current")::numeric / ("progress_target")::numeric) * (100)::numeric), (100)::numeric)
    ELSE (0)::numeric
END) STORED,
    "earned_at" timestamp with time zone,
    "is_earned" boolean DEFAULT false,
    "shared_to_circle" boolean DEFAULT false,
    "is_showcased" boolean DEFAULT false,
    "notified_at_50" boolean DEFAULT false,
