CREATE OR REPLACE VIEW "public"."v_recent_escalation_attempts" WITH ("security_invoker"='true') AS
 SELECT "id",
    "user_id",
    "event_type",
    "severity",
    "attempted_changes",
    "reason",
    "created_at"
   FROM "public"."security_audit_log"
  WHERE (("event_type" = 'PRIVILEGE_ESCALATION_ATTEMPT'::"text") AND ("created_at" > ("now"() - '24:00:00'::interval)))
  ORDER BY "created_at" DESC;


ALTER VIEW "public"."v_recent_escalation_attempts" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_recent_escalation_attempts" IS 'Shows all privilege escalation attempts from the last 24 hours for investigation. Uses SECURITY INVOKER.';



CREATE OR REPLACE VIEW "public"."v_repeat_escalation_offenders" WITH ("security_invoker"='true') AS
 SELECT "user_id",
    "count"(*) AS "attempt_count",
    "max"("created_at") AS "last_attempt",
    "array_agg"(DISTINCT "severity" ORDER BY "severity" DESC) AS "severity_levels"
   FROM "public"."security_audit_log"
  WHERE (("event_type" = 'PRIVILEGE_ESCALATION_ATTEMPT'::"text") AND ("created_at" > ("now"() - '7 days'::interval)))
  GROUP BY "user_id"
 HAVING ("count"(*) > 1)
  ORDER BY ("count"(*)) DESC;


ALTER VIEW "public"."v_repeat_escalation_offenders" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_repeat_escalation_offenders" IS 'Identifies users with multiple escalation attempts (potential attackers). Uses SECURITY INVOKER.';



