COMMENT ON COLUMN "public"."weekly_summaries"."mood_by_day" IS 'Average mood by day of week: {"mon": 3.5, "tue": 4.0, ...}';



COMMENT ON COLUMN "public"."weekly_summaries"."circle_checkin_count" IS 'Number of circle check-ins posted this week';



COMMENT ON COLUMN "public"."weekly_summaries"."exercise_minutes" IS 'Total exercise minutes this week';



COMMENT ON COLUMN "public"."weekly_summaries"."patterns_detected" IS 'Detected patterns: [{"type": "time", "description": "...", "confidence": 0.8}]';



COMMENT ON COLUMN "public"."weekly_summaries"."ai_insight" IS 'AI-generated personalized insight (2-3 sentences)';



COMMENT ON COLUMN "public"."weekly_summaries"."ai_recommendations" IS 'AI recommendations: [{"title": "...", "reason": "..."}]';



CREATE TABLE IF NOT EXISTS "public"."xp_transactions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "user_id" "uuid" NOT NULL,
    "amount" integer NOT NULL,
    "source" "text" NOT NULL,
    "source_id" "text",
    "description" "text",
    "multiplier_applied" numeric(3,2) DEFAULT 1.0,
    "base_amount" integer,
    "created_at" timestamp with time zone DEFAULT "now"()
);


ALTER TABLE "public"."xp_transactions" OWNER TO "postgres";


