CREATE POLICY "Accessibility audits - admin only" ON "public"."accessibility_audits" USING (false);



CREATE POLICY "Active audio readable by authenticated users" ON "public"."localized_audio" FOR SELECT USING ((("auth"."role"() = 'authenticated'::"text") AND ("is_active" = true)));



CREATE POLICY "Active crisis resources readable" ON "public"."localized_crisis_resources" FOR SELECT USING ((("auth"."role"() = 'authenticated'::"text") AND ("is_active" = true)));



CREATE POLICY "Active languages readable by authenticated users" ON "public"."supported_languages" FOR SELECT USING (("is_active" = true));



CREATE POLICY "Admin manages family group" ON "public"."family_groups" USING (("auth"."uid"() = "admin_user_id"));



CREATE POLICY "Admin manages family members" ON "public"."family_members" USING ((EXISTS ( SELECT 1
   FROM "public"."family_groups" "fg"
  WHERE (("fg"."id" = "family_members"."family_id") AND ("fg"."admin_user_id" = "auth"."uid"())))));



CREATE POLICY "Admin manages invitations" ON "public"."family_invitations" USING ((EXISTS ( SELECT 1
   FROM "public"."family_groups" "fg"
  WHERE (("fg"."id" = "family_invitations"."family_id") AND ("fg"."admin_user_id" = "auth"."uid"())))));



CREATE POLICY "Admins read all audit logs" ON "public"."audit_log" FOR SELECT TO "authenticated" USING (false);



CREATE POLICY "Allow anonymous insert" ON "public"."waitlist" FOR INSERT TO "anon" WITH CHECK (true);



CREATE POLICY "Anonymous rooms are public" ON "public"."anonymous_rooms" FOR SELECT USING (("is_active" = true));



CREATE POLICY "Anyone can read approved testimonials" ON "public"."testimonials" FOR SELECT USING (("approved" = true));



CREATE POLICY "Anyone can read available voices" ON "public"."available_voices" FOR SELECT USING (("is_active" = true));



CREATE POLICY "Anyone can read methodology info" ON "public"."methodology_info" FOR SELECT USING (true);



CREATE POLICY "Anyone can read quick variants" ON "public"."quest_quick_variants" FOR SELECT USING (true);



CREATE POLICY "Anyone can view active challenge templates" ON "public"."family_challenge_templates" FOR SELECT USING (("is_active" = true));



CREATE POLICY "Anyone can view active templates" ON "public"."share_card_templates" FOR SELECT TO "authenticated" USING (("is_active" = true));



CREATE POLICY "Anyone can view active together templates" ON "public"."together_templates" FOR SELECT USING (("is_active" = true));



CREATE POLICY "Anyone can view approved creators" ON "public"."creators" FOR SELECT USING (("status" = 'approved'::"text"));



CREATE POLICY "Anyone can view badges" ON "public"."badges" FOR SELECT TO "authenticated" USING (true);



CREATE POLICY "Anyone can view content age ratings" ON "public"."content_age_ratings" FOR SELECT USING (true);



CREATE POLICY "Anyone can view exercises" ON "public"."exercises" FOR SELECT TO "authenticated" USING (true);



CREATE POLICY "Anyone can view level thresholds" ON "public"."level_thresholds" FOR SELECT TO "authenticated" USING (true);



CREATE POLICY "Anyone can view published content" ON "public"."creator_content" FOR SELECT USING (("status" = 'published'::"text"));



CREATE POLICY "Anyone can view published series" ON "public"."content_series" FOR SELECT USING (("status" = 'published'::"text"));



CREATE POLICY "Anyone can view quest templates" ON "public"."quest_templates" FOR SELECT TO "authenticated" USING (true);



CREATE POLICY "Anyone can view ratings" ON "public"."content_ratings" FOR SELECT USING (true);



CREATE POLICY "Anyone can view seasonal events" ON "public"."seasonal_events" FOR SELECT TO "authenticated" USING (true);



CREATE POLICY "Anyone can view skill thresholds" ON "public"."skill_thresholds" FOR SELECT TO "authenticated" USING (true);



CREATE POLICY "Approved wisdom is public" ON "public"."community_wisdom" FOR SELECT USING ((("status" = 'approved'::"text") OR ("user_id" = "auth"."uid"())));



CREATE POLICY "Assignments visible to connection" ON "public"."therapist_assignments" FOR SELECT USING (("connection_id" IN ( SELECT "therapy_connections"."id"
   FROM "public"."therapy_connections"
  WHERE (("therapy_connections"."client_id" = "auth"."uid"()) OR ("therapy_connections"."therapist_id" IN ( SELECT "therapist_accounts"."id"
           FROM "public"."therapist_accounts"
          WHERE ("therapist_accounts"."user_id" = "auth"."uid"())))))));



CREATE POLICY "Audit logs are immutable" ON "public"."pattern_access_audit" FOR UPDATE USING (false);



CREATE POLICY "Audit logs cannot be manually deleted" ON "public"."pattern_access_audit" FOR DELETE USING (false);



